        "invoiceCountryInfoConsumer_msg": "\u0647\u0630\u0627 \u0645\u0637\u0644\u0648\u0628 \u0644\u062D\u0633\u0627\u0628 \u0636\u0631\u064A\u0628\u0629 \u0627\u0644\u0642\u064A\u0645\u0629 \u0627\u0644\u0645\u0636\u0627\u0641\u0629.",
        "invoiceCountry_label": "\u0627\u0644\u0628\u0644\u062F",
        "invoiceData_msg": "\u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u0641\u0627\u062A\u0648\u0631\u0629",
        "invoiceMailBodyAutomatic_msg": "\u0647\u0646\u0627\u0643 \u0641\u0627\u062A\u0648\u0631\u0629 \u062C\u062F\u064A\u062F\u0629 \u0645\u062A\u0648\u0641\u0631\u0629\u060C \u062A\u062D\u0645\u0644 \u0627\u0644\u0631\u0642\u0645 {1}. \u064A\u0645\u0643\u0646\u0643 \u062A\u062D\u0645\u064A\u0644\u0647\u0627 \u0645\u0646 \u062E\u0644\u0627\u0644 {2}. \u0633\u064A\u062A\u0645 \u062E\u0635\u0645 \u0627\u0644\u0645\u062C\u0645\u0648\u0639 \u0627\u0644\u0643\u0644\u064A \u062A\u0644\u0642\u0627\u0626\u064A\u064B\u0627.",
        "invoiceMailBodyOnAccount_msg": "\u0647\u0646\u0627\u0643 \u0641\u0627\u062A\u0648\u0631\u0629 \u062C\u062F\u064A\u062F\u0629 \u0645\u062A\u0648\u0641\u0651\u0631\u0629\u060C \u062A\u062D\u0645\u0644 \u0627\u0644\u0631\u0642\u0645 {1}. \u064A\u0645\u0643\u0646\u0643 \u062A\u0646\u0632\u064A\u0644\u0647\u0627 \u0645\u0646 \u062E\u0644\u0627\u0644 {2}. \u0648\u0645\u0647\u0644\u0629 \u0627\u0644\u062F\u0641\u0639 \u0647\u064A 7 \u0623\u064A\u0651\u0627\u0645 \u0628\u0639\u062F \u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0641\u0627\u062A\u0648\u0631\u0629.",
        "invoiceMailSubject_msg": "\u0641\u0627\u062A\u0648\u0631\u0629 \u062C\u062F\u064A\u062F\u0629 \u0645\u0646 \u062A\u0648\u062A\u0627\u0646\u0648\u062A\u0627",
        "invoiceNotPaidUser_msg": "\u0639\u0630\u0631\u0627 \u060C \u0644\u0627 \u064A\u0633\u0645\u062D \u0644\u0643 \u062D\u0627\u0644\u064A\u0627 \u0628\u0625\u0631\u0633\u0627\u0644 \u0631\u0633\u0627\u0626\u0644 \u0627\u0644\u0628\u0631\u064A\u062F \u0627\u0644\u0625\u0644\u0643\u062A\u0631\u0648\u0646\u064A.",
        "invoiceNotPaid_msg": "\u0639\u0641\u0648\u064B\u0627\u060C \u0644\u0627 \u064A\u064F\u0633\u0645\u062D \u0644\u0643 \u062D\u0627\u0644\u064A\u0651\u064B\u0627 \u0625\u0631\u0633\u0627\u0644 \u0623\u0648 \u062A\u0644\u0642\u064A \u0627\u0644\u0631\u0633\u0627\u0626\u0644 \u0627\u0644\u0625\u0644\u0643\u062A\u0631\u0648\u0646\u064A\u0651\u0629 \u0644\u0623\u0646 \u0625\u062D\u062F \u0641\u0648\u0627\u062A\u064A\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0642\u0644 \u063A\u064A\u0631 \u0645\u062F\u0641\u0648\u0639\u0629. \u0627\u0644\u0631\u062C\u0627\u0621 \u062A\u062D\u062F\u064A\u062B \u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u062F\u0641\u0639 \u0641\u064A '\u0627\u0644\u0625\u0639\u062F\u0627\u062F\u0627\u062A' \u21E6 '\u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u062F\u0641\u0639' \u0648\u062A\u0634\u063A\u064A\u0644 \u0627\u0644\u062F\u0641\u0639 \u0628\u0639\u062F \u0630\u0644\u0643.\n",
        "invoicePayConfirm_msg": "\u0633\u0646\u0642\u0648\u0645 \u0627\u0644\u0622\u0646 \u0628\u062E\u0635\u0645 \u0627\u0644\u0645\u0628\u0644\u063A \u0627\u0644\u062A\u0627\u0644\u064A : ",
        "invoicePaymentMethodInfo_msg": "\u064A\u0631\u062C\u0649 \u0627\u062E\u062A\u064A\u0627\u0631 \u0637\u0631\u064A\u0642\u0629 \u0627\u0644\u062F\u0641\u0639. \u0633\u064A\u062A\u0645 \u0625\u0636\u0627\u0641\u0629 \u0627\u0644\u0645\u0632\u064A\u062F \u0645\u0646 \u0627\u0644\u062E\u064A\u0627\u0631\u0627\u062A \u0641\u064A \u0627\u0644\u0645\u0633\u062A\u0642\u0628\u0644.",
