        "resetZoomFactor_action": "\u0625\u0639\u0627\u062F\u0629 \u062A\u0639\u064A\u064A\u0646 \u0639\u0627\u0645\u0644 \u0627\u0644\u062A\u0643\u0628\u064A\u0631",
