        "creditCardExprationDateInvalid_msg": "\u0424\u0430\u0440\u043C\u0430\u0442 \u0434\u0430\u0442\u044B \u043D\u0435\u043A\u0430\u0440\u044D\u043A\u0442\u043D\u044B.",
        "creditCardNumberFormat_msg": "\u041A\u0430\u043B\u0456 \u043B\u0430\u0441\u043A\u0430, \u0443\u0432\u044F\u0434\u0437\u0456 \u043D\u0443\u043C\u0430\u0440 \u0441\u0432\u0430\u0451\u0439 \u043A\u0440\u044D\u0434\u044B\u0442\u043D\u0430\u0439 \u043A\u0430\u0440\u0442\u043A\u0456.",
        "creditCardNumberInvalid_msg": "\u041D\u0443\u043C\u0430\u0440 \u043A\u0440\u044D\u0434\u044B\u0442\u043D\u0430\u0439 \u043A\u0430\u0440\u0442\u043A\u0456 \u043D\u0435\u043A\u0430\u0440\u044D\u043A\u0442\u043D\u044B.",
        "creditCardNumber_label": "\u041D\u0443\u043C\u0430\u0440 \u043A\u0440\u044D\u0434\u044B\u0442\u043A\u0456",
        "creditCardPaymentErrorVerificationNeeded_msg": "\u041A\u0430\u043B\u0456 \u043B\u0430\u0441\u043A\u0430, \u0430\u0431\u043D\u0430\u0432\u0456 \u043F\u043B\u0430\u0446\u0435\u0436\u043D\u044B\u044F \u0434\u0430\u043D\u044B\u044F. \u041F\u0430\u0441\u043B\u044F \u0433\u044D\u0442\u0430\u0433\u0430 \u0430\u0434\u0431\u0443\u0434\u0437\u0435\u0446\u0446\u0430 \u0441\u043F\u0440\u0430\u045E\u0434\u0436\u0430\u043D\u043D\u0435 \u043A\u0440\u044D\u0434\u044B\u0442\u043A\u0456, \u044F\u043A\u043E\u0435 \u043F\u0430\u0442\u0440\u0430\u0431\u0443\u0435\u0446\u0446\u0430 \u0442\u0432\u0430\u0456\u043C \u0431\u0430\u043D\u043A\u0430\u043C.",
        "creditCardPendingVerification_msg": "\u0421\u043F\u0440\u0430\u045E\u0434\u0436\u0430\u043D\u043D\u0435 \u0442\u0432\u0430\u0451\u0439 \u043A\u0440\u044D\u0434\u044B\u0442\u043A\u0456 \u044F\u0448\u0447\u044D \u043D\u044F \u0441\u043A\u043E\u043D\u0447\u0430\u043D\u0430. \u041A\u0430\u043B\u0456 \u043B\u0430\u0441\u043A\u0430, \u043F\u0430\u0441\u043F\u0440\u0430\u0431\u0443\u0439 \u0441\u043F\u0440\u0430\u045E\u0434\u0437\u0456\u0446\u044C \u0441\u0432\u0430\u044E \u043A\u0440\u044D\u0434\u044B\u0442\u043A\u0443 \u043F\u0430\u0437\u043D\u0435\u0439, \u043A\u0430\u043B\u0456 \u0433\u044D\u0442\u0430\u044F \u043F\u0440\u0430\u0431\u043B\u0435\u043C\u0430 \u0437\u0430\u0441\u0442\u0430\u0432\u0430\u0446\u044C\u043C\u0435\u0446\u0446\u0430.",
        "creditCardVerificationFailed_msg": "\u041F\u0440\u0430\u0431\u0430\u0447, \u043D\u0435 \u0430\u0442\u0440\u044B\u043C\u0430\u043B\u0430\u0441\u044F \u0441\u043F\u0440\u0430\u045E\u0434\u0437\u0456\u0446\u044C \u0442\u0432\u0430\u044E \u043A\u0440\u044D\u0434\u044B\u0442\u043A\u0443. \u041F\u0430\u0441\u043F\u0440\u0430\u0431\u0443\u0439 \u0456\u0437\u043D\u043E\u045E \u043F\u0430\u0437\u043D\u0435\u0439, \u0430\u043B\u044C\u0431\u043E \u0441\u043A\u0430\u0440\u044B\u0441\u0442\u0430\u0439\u0441\u044F \u0456\u043D\u0448\u044B\u043C \u0441\u043F\u043E\u0441\u0430\u0431\u0430\u043C \u0430\u043F\u043B\u0430\u0442\u044B.",
        "creditCardVerificationLimitReached_msg": "\u041B\u0456\u043C\u0456\u0442 \u0441\u043F\u0440\u0430\u045E\u0434\u0436\u0430\u043D\u043D\u044F \u043A\u0440\u044D\u0434\u044B\u0442\u043A\u0456 \u0432\u044B\u0447\u0430\u0440\u043F\u0430\u043D\u044B. \u041A\u0430\u043B\u0456 \u043B\u0430\u0441\u043A\u0430, \u043F\u0430\u0441\u043F\u0440\u0430\u0431\u0443\u0439 \u0456\u0437\u043D\u043E\u045E \u043F\u0440\u0430\u0437 \u043D\u0435\u043A\u0430\u043B\u044C\u043A\u0456 \u0433\u0430\u0434\u0437\u0456\u043D \u0456 \u045E\u043F\u044D\u045E\u043D\u0456\u0441\u044F, \u0448\u0442\u043E \u045E\u0432\u0435\u0434\u0437\u0435\u043D\u044B\u044F \u0434\u0430\u043D\u044B\u044F \u043A\u0430\u0440\u044D\u043A\u0442\u043D\u044B\u044F. \u0421\u043A\u0430\u043D\u0442\u0430\u043A\u0442\u0443\u0439\u0441\u044F \u0441\u0430 \u0441\u0432\u0430\u0456\u043C \u0431\u0430\u043D\u043A\u0430\u043C, \u043A\u0430\u043B\u0456 \u043D\u044F \u045E\u0434\u0430\u0441\u0446\u0430 \u0441\u043F\u0440\u0430\u045E\u0434\u0437\u0456\u0446\u044C \u043A\u0440\u044D\u0434\u044B\u0442\u043A\u0443.",
        "creditCardVerificationNeededPopup_msg": "\u0422\u0432\u0430\u044F \u043A\u0440\u044D\u0434\u044B\u0442\u043A\u0430 \u043C\u0443\u0441\u0456\u0446\u044C \u0431\u044B\u0446\u044C \u043F\u0440\u0430\u0432\u0435\u0440\u0430\u043D\u0430 \u0442\u0432\u0430\u0456\u043C \u0431\u0430\u043D\u043A\u0430\u043C. \u0414\u0437\u0435\u043B\u044F \u0433\u044D\u0442\u0430\u0433\u0430 \u0431\u0443\u0434\u0437\u0435 \u0430\u0434\u0447\u044B\u043D\u0435\u043D\u0430 \u043D\u043E\u0432\u0430\u0435 \u0430\u043A\u043D\u043E.",
        "creditCardVerification_msg": "\u0417\u0430\u0440\u0430\u0437 \u0442\u0432\u0430\u044F \u043A\u0440\u044D\u0434\u044B\u0442\u043A\u0430 \u0441\u043F\u0440\u0430\u045E\u0434\u0436\u0432\u0430\u0435\u0446\u0446\u0430...",
        "creditUsageOptions_msg": "\u0413\u0440\u043E\u0448\u044B \u043D\u0430 \u0440\u0430\u0445\u0443\u043D\u043A\u0443 \u043C\u043E\u0436\u043D\u0430 \u0432\u044B\u043A\u0430\u0440\u044B\u0441\u0442\u043E\u045E\u0432\u0430\u0446\u044C, \u043A\u0430\u0431 \u043D\u0430\u0431\u044B\u0446\u044C \u0440\u043E\u0437\u043D\u044B\u044F \u0442\u0430\u0440\u044B\u0444\u043D\u044B\u044F \u043F\u0430\u043A\u0435\u0442\u044B (\u0433\u043B. '\u041D\u0430\u043B\u0430\u0434\u044B' \u21E8 '\u041F\u0430\u0434\u043F\u0456\u0441\u043A\u0430'), \u0446\u0456 \u043C\u043E\u0436\u043D\u0430 \u0437\u0430\u0445\u043E\u045E\u0432\u0430\u0446\u044C, \u043A\u0430\u0431 \u0432\u044B\u043A\u0430\u0440\u044B\u0441\u0442\u0430\u0446\u044C \u043F\u0440\u044B \u0430\u043F\u043B\u0430\u0446\u0435 \u043D\u0430\u0441\u0442\u0443\u043F\u043D\u0430\u0433\u0430 \u043F\u0435\u0440\u044B\u044F\u0434\u0443 \u043F\u0430\u0434\u043F\u0456\u0441\u043A\u0456. \u0413\u0440\u043E\u0448\u044B \u0437 \u043F\u0430\u0434\u0430\u0440\u0443\u043D\u043A\u0430\u0432\u044B\u0445 \u043A\u0430\u0440\u0442\u0430\u043A \u043D\u044F \u043C\u0430\u044E\u0446\u044C \u0442\u044D\u0440\u043C\u0456\u043D\u0443 \u0434\u0437\u0435\u044F\u043D\u043D\u044F.",
