        "importExport_action": "\u0406\u043C\u043F\u0430\u0440\u0442\u0430\u0432\u0430\u0446\u044C/\u044D\u043A\u0441\u043F\u0430\u0440\u0442\u0430\u0432\u0430\u0446\u044C",
        "importInvalidDatesInEvent_msg": "{amount} \u0437 {total} \u0441\u0443\u0441\u0442\u0440\u044D\u0447\u0430\u045E \u043C\u0430\u044E\u0446\u044C \u043D\u0435\u0434\u0430\u043F\u0443\u0448\u0447\u0430\u043B\u044C\u043D\u044B\u044F \u0434\u0430\u043D\u044B\u044F \u0456 \u0442\u0430\u043C\u0443 \u043D\u0435 \u0456\u043C\u043F\u0430\u0440\u0442\u0430\u0432\u0430\u0446\u044C\u043C\u0443\u0446\u0446\u0430.",
        "importPre1970StartInEvent_msg": "{amount} \u0437 {total} \u043F\u0430\u0434\u0437\u0435\u0439 \u043F\u0430\u0447\u044B\u043D\u0430\u044E\u0446\u0446\u0430 \u0430\u0431\u043E \u0441\u043A\u0430\u043D\u0447\u0432\u0430\u044E\u0446\u0446\u0430 \u0434\u0430 1970 \u0433\u043E\u0434\u0443 \u0456 \u0442\u0430\u043C\u0443 \u043D\u0435 \u0456\u043C\u043F\u0430\u0440\u0442\u0430\u0432\u0430\u0446\u044C\u043C\u0443\u0446\u0446\u0430.",
