        "otherPaymentProviderError_msg": "\u041F\u043B\u0430\u0446\u0435\u0436\u043D\u044B \u043F\u0440\u0430\u0432\u0430\u0439\u0434\u0430\u0440 \u043F\u0430\u0432\u0435\u0434\u0430\u043C\u0456\u045E \u043F\u0430\u043C\u044B\u043B\u043A\u0443. \u041A\u0430\u043B\u0456 \u043B\u0430\u0441\u043A\u0430, \u043F\u0430\u0441\u043F\u0440\u0430\u0431\u0443\u0439 \u0456\u0437\u043D\u043E\u045E \u043F\u0430\u0437\u043D\u0435\u0439.",
        "other_label": "\u0406\u043D\u0448\u044B",
        "outdatedClientWarningMailBody_msg": "\u041F\u0440\u044B\u0432\u0456\u0442\u0430\u043D\u043D\u0456,<br>\n\n\u043D\u0430 \u0434\u0430\u0434\u0437\u0435\u043D\u044B \u043C\u043E\u043C\u0430\u043D\u0442 \u0442\u044B \u043A\u0430\u0440\u044B\u0441\u0442\u0430\u0435\u0448\u0441\u044F \u0441\u0430\u0441\u0442\u0430\u0440\u044D\u043B\u0430\u0439 \u0432\u0435\u0440\u0441\u0456\u044F\u0439 \u0422\u0443\u0442\u0430\u043D\u043E\u0442\u044B. \u041F\u0430\u0434\u0442\u0440\u044B\u043C\u043A\u0430 \u0433\u044D\u0442\u0430\u0439 \u0432\u0435\u0440\u0441\u0456\u0456 \u0431\u0443\u0434\u0437\u0435 \u0441\u043F\u044B\u043D\u0435\u043D\u0430 \u043F\u0440\u0430\u0437 \u043D\u0435\u043A\u0430\u043B\u044C\u043A\u0456 \u0434\u0437\u0451\u043D.<br><br>\n\n\u041A\u0430\u043B\u0456 \u043B\u0430\u0441\u043A\u0430, \u0430\u0431\u043D\u0430\u0432\u0456 \u0441\u0432\u0430\u044E \u043F\u0440\u0430\u0433\u0440\u0430\u043C\u0443 \u0442\u0443\u0442: {downloadLink} <br><br>\n\n\u0422\u0430\u043A\u0441\u0430\u043C\u0430 \u043F\u0440\u0430\u0432\u0435\u0440, \u0446\u0456 \u043D\u0435 \u043A\u0430\u0440\u044B\u0441\u0442\u0430\u0435\u0448\u0441\u044F \u0442\u044B \u0441\u0430\u0441\u0442\u0430\u0440\u044D\u043B\u044B\u043C\u0456 \u0432\u0435\u0440\u0441\u0456\u044F\u043C\u0456 \u0422\u0443\u0442\u0430\u043D\u043E\u0442\u044B \u043D\u0430 \u0456\u043D\u0448\u044B\u0445 \u043F\u0440\u044B\u043B\u0430\u0434\u0430\u0445. \u0421\u0456\u0441\u0442\u044D\u043C\u0430 \u043F\u0435\u0440\u0430\u0441\u0442\u0430\u043D\u0435 \u0434\u0430\u0441\u044B\u043B\u0430\u0446\u044C \u0433\u044D\u0442\u044B \u0456\u043C\u044D\u0439\u043B \u0442\u0430\u0434\u044B, \u043A\u0430\u043B\u0456 \u045E\u0441\u0435 \u0442\u0432\u0430\u0435 \u043A\u043B\u0456\u0435\u043D\u0442\u044B \u0422\u0443\u0442\u0430\u043D\u043E\u0442\u044B \u0431\u0443\u0434\u0443\u0446\u044C \u0430\u043A\u0442\u0443\u0430\u043B\u044C\u043D\u044B\u043C\u0456.<br><br>\n\u0414\u0437\u044F\u043A\u0443\u0439!<br><br>\n\n\u0422\u0432\u0430\u044F \u041A\u0430\u043C\u0430\u043D\u0434\u0430 \u0422\u0443\u0442\u0430\u043D\u043E\u0442\u044B",
        "outdatedClientWarningMailSubject_msg": "\u041A\u0430\u043B\u0456 \u043B\u0430\u0441\u043A\u0430, \u0430\u0431\u043D\u0430\u0432\u0456 Tutanota",
        "outdatedClient_msg": "\u041A\u0430\u043B\u0456 \u043B\u0430\u0441\u043A\u0430, \u0430\u0431\u043D\u0430\u0432\u0456 \u0422\u0443\u0442\u0430\u043D\u043E\u0442\u0443. \u0414\u0430\u0434\u0437\u0435\u043D\u0430\u044F \u045E\u0441\u0442\u0430\u043B\u044F\u0432\u0430\u043D\u0430\u044F \u0432\u0435\u0440\u0441\u0456\u044F \u0437\u0430\u0441\u0442\u0430\u0440\u0430\u044F \u0456 \u0431\u043E\u043B\u044C\u0448 \u043D\u0435 \u043F\u0430\u0434\u0442\u0440\u044B\u043C\u043B\u0456\u0432\u0430\u0435\u0446\u0446\u0430.",
        "outlookInvoiceMailBodyAutomatic_msg": "\u0434\u0430 \u0433\u044D\u0442\u0430\u0433\u0430 \u043B\u0456\u0441\u0442\u0430 \u0431\u044B\u045E \u0434\u0430\u043B\u0443\u0447\u0430\u043D\u044B \u043D\u043E\u0432\u044B \u0440\u0430\u0445\u0443\u043D\u0430\u043A \u0437\u0430 \u0422\u0443\u0442\u0430\u043D\u043E\u0442\u0443 \u043F\u0430\u0434 \u043D\u0443\u043C\u0430\u0440\u0430\u043C {1}. \u0421\u0443\u043C\u0430 \u0437 \u043A\u0432\u0456\u0442\u0430\u043D\u0446\u044B\u0456 \u0431\u0443\u0434\u0437\u0435 \u0441\u043F\u0456\u0441\u0430\u043D\u0430 \u0437 \u0442\u0432\u0430\u0439\u0433\u043E \u0440\u0430\u0445\u0443\u043D\u043A\u0443 \u0430\u045E\u0442\u0430\u043C\u0430\u0442\u044B\u0447\u043D\u0430. \u0422\u0430\u043A\u0441\u0430\u043C\u0430 \u0442\u044B \u043C\u043E\u0436\u0430\u0448 \u043F\u0440\u0430\u0433\u043B\u044F\u0434\u0437\u0435\u0446\u044C \u0443\u0441\u0435 \u0441\u0432\u0430\u0435 \u043A\u0432\u0456\u0442\u0430\u043D\u0446\u044B\u0456 \u045E {2}",
        "outlookInvoiceMailBodyOnAccount_msg": "\u0434\u0430 \u0433\u044D\u0442\u0430\u0433\u0430 \u0456\u043C\u044D\u0439\u043B\u0443 \u0431\u044B\u045E \u0434\u0430\u043B\u0443\u0447\u0430\u043D\u044B \u0444\u0430\u0439\u043B \u0437 \u043D\u043E\u0432\u044B\u043C \u0440\u0430\u0445\u0443\u043D\u043A\u0430\u043C \u0437 \u043D\u0443\u043C\u0430\u0440\u0430\u043C {1}. \u0410\u043F\u043B\u0430\u0442\u0430 \u0440\u0430\u0445\u0443\u043D\u043A\u0443 \u043F\u0430\u0441\u043B\u044F \u044F\u0433\u043E\u043D\u0430\u0433\u0430 \u0430\u0442\u0440\u044B\u043C\u0430\u043D\u043D\u044F \u0441\u043A\u043B\u0430\u0434\u0430\u0435 7 \u0434\u0437\u0451\u043D. \u0422\u0430\u043A\u0441\u0430\u043C\u0430 \u0442\u044B \u043C\u043E\u0436\u0430\u0448 \u043F\u0440\u0430\u0433\u043B\u044F\u0434\u0437\u0435\u0446\u044C \u0443\u0441\u0435 \u0441\u0432\u0430\u0435  \u0440\u0430\u0445\u0443\u043D\u043A\u0443 \u045E {2}.",
        "outOfOfficeDefaultSubject_msg": "\u042F \u043F\u0430-\u0437\u0430 \u043E\u0444\u0456\u0441\u0430\u043C.",
        "outOfOfficeDefault_msg": "\u0412\u0456\u0442\u0430\u044E,\n<br>\n<br>\u0434\u0437\u044F\u043A\u0443\u0439 \u0437\u0430 \u0412\u0430\u0448 \u043B\u0456\u0441\u0442. \u042F \u0437\u043D\u0430\u0445\u043E\u0434\u0436\u0443\u0441\u044F \u043F\u0430-\u0437\u0430 \u043E\u0444\u0456\u0441\u0430\u043C, \u0430\u043B\u0435 \u043C\u0443\u0448\u0443 \u0445\u0443\u0442\u043A\u0430 \u0432\u044F\u0440\u043D\u0443\u0446\u0446\u0430. \u0414\u0430 \u0433\u044D\u0442\u0430\u0433\u0430 \u0447\u0430\u0441\u0443 \u044F \u0431\u0443\u0434\u0443 \u043C\u0435\u0446\u044C \u0430\u0431\u043C\u0435\u0436\u0430\u0432\u0430\u043D\u044B \u0434\u043E\u0441\u0442\u0443\u043F \u0434\u0430 \u043C\u0430\u0451\u0439 \u044D\u043B\u0435\u043A\u0442\u0440\u043E\u043D\u0430\u0439 \u043F\u0430\u0448\u0442\u043E\u0432\u0430\u0439 \u0441\u043A\u0440\u044B\u043D\u043A\u0456.\n<br>\n<br>\u0421\u0430\u0440\u0434\u044D\u0447\u043D\u044B\u044F \u043F\u0440\u044B\u0432\u0456\u0442\u0430\u043D\u043D\u0456",
        "outOfOfficeEveryone_msg": "\u0414\u0430 \u045E\u0441\u0456\u0445",
        "outOfOfficeExternal_msg": "\u041F\u0430-\u0437\u0430 \u0442\u0432\u0430\u0451\u0439 \u0430\u0440\u0433\u0430\u043D\u0456\u0437\u0430\u0446\u044B\u044F\u0439",
        "outOfOfficeInternal_msg": "\u0423\u043D\u0443\u0442\u0440\u044B \u0442\u0432\u0430\u0451\u0439 \u0430\u0440\u0433\u0430\u043D\u0456\u0437\u0430\u0446\u044B\u0456",
        "outOfOfficeMessageInvalid_msg": "\u041D\u0430\u0433\u043E\u0434\u0430 (\u0446)\u0456 \u043F\u0430\u0432\u0435\u0434\u0430\u043C\u043B\u0435\u043D\u043D\u0435 \u043D\u0435\u043A\u0430\u0440\u044D\u043A\u0442\u043D\u044B\u044F.\n\u041F\u0443\u0441\u0442\u0430\u044F \u043D\u0430\u0433\u043E\u0434\u0430 \u0446\u0456 \u043F\u0443\u0441\u0442\u043E\u0435 \u043F\u0430\u0432\u0435\u0434\u0430\u043C\u043B\u0435\u043D\u043D\u0435 \u043D\u0435\u0434\u0430\u0437\u0432\u043E\u043B\u0435\u043D\u044B\u044F.\n\u041C\u0430\u043A\u0441\u0456\u043C\u0430\u043B\u044C\u043D\u044B \u043F\u0430\u043C\u0435\u0440 \u043D\u0430\u0433\u043E\u0434\u044B: 128 \u0437\u043D\u0430\u043A\u0430\u045E.\n\u041C\u0430\u043A\u0441\u0456\u043C\u0430\u043B\u044C\u043D\u044B \u043F\u0430\u043C\u0435\u0440 \u043F\u0430\u0432\u0435\u0434\u0430\u043C\u043B\u0435\u043D\u043D\u044F: 20 \u043A\u0411.",
