        "paymentMethodAccountBalance_label": "\u0411\u0430\u043B\u0430\u043D\u0441 \u0430\u043A\u0430\u045E\u043D\u0442\u0430",
        "paymentMethodAccountBalance_msg": "\u0422\u044B \u0430\u043F\u043B\u0430\u0447\u0432\u0430\u0435\u0448 \u0441\u0432\u043E\u0439 \u0430\u043A\u0430\u045E\u043D\u0442 \u0433\u0440\u0430\u0448\u044B\u043C\u0430, \u0448\u0442\u043E \u043B\u044F\u0436\u0430\u0446\u044C \u043D\u0430 \u0442\u0432\u0430\u0456\u043C \u0430\u043A\u0430\u045E\u043D\u0446\u0435. \u0422\u044B \u043C\u043E\u0436\u0430\u0448 \u043F\u0430\u043F\u043E\u045E\u043D\u0456\u0446\u044C \u0441\u0432\u043E\u0439 \u0431\u0430\u043B\u0430\u043D\u0441 \u0437 \u0434\u0430\u043F\u0430\u043C\u043E\u0433\u0430\u0439 \u043F\u0430\u0434\u0430\u0440\u0443\u043D\u043A\u0430\u0432\u044B\u0445 \u043A\u0430\u0440\u0442\u0430\u043A.",
        "paymentMethodCreditCard_label": "\u041A\u0440\u044D\u0434\u044B\u0442\u043A\u0430",
