        "password2Neutral_msg": "\u041C\u043E\u043B\u044F, \u043F\u043E\u0442\u0432\u044A\u0440\u0434\u0435\u0442\u0435 \u0432\u0430\u0448\u0430\u0442\u0430 \u043F\u0430\u0440\u043E\u043B\u0430 .",
        "passwordEnterNeutral_msg": "\u041C\u043E\u043B\u044F, \u0432\u044A\u0432\u0435\u0434\u0435\u0442\u0435 \u043F\u0430\u0440\u043E\u043B\u0430\u0442\u0430 \u0441\u0438 \u0437\u0430 \u043F\u043E\u0442\u0432\u044A\u0440\u0436\u0434\u0435\u043D\u0438\u0435.",
        "passwordFor_label": "\u041F\u0430\u0440\u043E\u043B\u0430 \u0437\u0430 {1}",
        "passwordImportance_msg": "\u041C\u043E\u043B\u044F \u0437\u0430\u043F\u0430\u0437\u0435\u0442\u0435 \u0442\u0430\u0437\u0438 \u043F\u0430\u0440\u043E\u043B\u0430 \u043D\u0430 \u0441\u0438\u0433\u0443\u0440\u043D\u043E \u043C\u044F\u0441\u0442\u043E.  \u041D\u0438\u0435 \u043D\u044F\u043C\u0430 \u0434\u0430 \u043C\u043E\u0436\u0435\u043C \u0434\u0430 \u0432\u044A\u0437\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u043C \u0412\u0430\u0448\u0430\u0442\u0430 \u043F\u0430\u0440\u043E\u043B\u0430 \u0438\u043B\u0438 \u0434\u0430 \u0430\u043D\u0443\u043B\u0438\u0440\u0430\u043C\u0435 \u0412\u0430\u0448\u0438\u044F \u043F\u0440\u043E\u0444\u0438\u043B, \u0437\u0430\u0449\u043E\u0442\u043E \u0432\u0441\u0438\u0447\u043A\u0438 \u0434\u0430\u043D\u043D\u0438 \u0441\u0430 \u043A\u0440\u0438\u043F\u0442\u0438\u0440\u0430\u043D\u0438.",
