        "errorReport_label": "\u0391\u03C4\u03C5\u03C7\u03AF\u03B1!",
        "eventCancelled_msg": "\u0391\u03BA\u03C5\u03C1\u03CE\u03B8\u03B7\u03BA\u03B5: {event}",
        "eventCopy_msg": "\u0391\u03C5\u03C4\u03CC \u03C4\u03BF \u03C3\u03C5\u03BC\u03B2\u03AC\u03BD \u03B5\u03C3\u03C4\u03AC\u03BB\u03B7 \u03B1\u03C0\u03CC \u03AC\u03BB\u03BB\u03BF \u03B7\u03BC\u03B5\u03C1\u03BF\u03BB\u03CC\u03B3\u03B9\u03BF. \u039F\u03B9 \u03B1\u03BB\u03BB\u03B1\u03B3\u03AD\u03C2 \u03C3\u03C4\u03BF \u03C3\u03C5\u03BC\u03B2\u03AC\u03BD \u03B8\u03B1 \u03B5\u03AF\u03BD\u03B1\u03B9 \u03BF\u03C1\u03B1\u03C4\u03AD\u03C2 \u03BC\u03CC\u03BD\u03BF \u03C3\u03C4\u03BF \u03B4\u03B9\u03BA\u03CC \u03C3\u03B1\u03C2 \u03B7\u03BC\u03B5\u03C1\u03BF\u03BB\u03CC\u03B3\u03B9\u03BF.",
        "eventInviteMail_msg": "\u03A0\u03C1\u03CC\u03C3\u03BA\u03BB\u03B7\u03C3\u03B7: {event}",
        "eventNotificationUpdated_msg": "\u03A4\u03BF \u03C3\u03C5\u03BC\u03B2\u03AC\u03BD \u03B5\u03BD\u03B7\u03BC\u03B5\u03C1\u03CE\u03B8\u03B7\u03BA\u03B5 \u03C3\u03C4\u03BF \u03B7\u03BC\u03B5\u03C1\u03BF\u03BB\u03CC\u03B3\u03B9\u03CC \u03C3\u03B1\u03C2.",
