        "importEndNotAfterStartInEvent_msg": "{amount} \u03B1\u03C0\u03CC {total} \u03C3\u03C5\u03BC\u03B2\u03AC\u03BD\u03C4\u03B1 \u03B4\u03B5\u03BD \u03AD\u03C7\u03BF\u03C5\u03BD \u03C4\u03B7\u03BD \u03B7\u03BC\u03B5\u03C1\u03BF\u03BC\u03B7\u03BD\u03AF\u03B1 \u03AD\u03BD\u03B1\u03C1\u03BE\u03B7\u03C2 \u03C0\u03C1\u03B9\u03BD \u03C4\u03B7\u03BD \u03B7\u03BC\u03B5\u03C1\u03BF\u03BC\u03B7\u03BD\u03AF\u03B1 \u03BB\u03AE\u03BE\u03B7\u03C2 \u03BA\u03B1\u03B9 \u03B4\u03B5\u03BD \u03B8\u03B1 \u03B5\u03B9\u03C3\u03B1\u03C7\u03B8\u03BF\u03CD\u03BD.",
        "importEventExistingUid_msg": "{amount} \u03B1\u03C0\u03BF \u03C4\u03B9\u03C2 {total} \u03B5\u03BA\u03B4\u03B7\u03BB\u03CE\u03C3\u03B5\u03B9\u03C2 \u03C5\u03C0\u03AC\u03C1\u03C7\u03BF\u03C5\u03BD \u03AE\u03B4\u03B7 \u03BA\u03B1\u03B9 \u03B4\u03B5\u03BD \u03B8\u03B1 \u03B5\u03C0\u03B5\u03B3\u03B3\u03C1\u03B1\u03C6\u03BF\u03CD\u03BD. \u0398\u03B1 \u03C3\u03C5\u03BD\u03B5\u03C7\u03B9\u03C3\u03C4\u03B5\u03AF \u03B7 \u03B5\u03C0\u03B5\u03B3\u03B3\u03C1\u03B1\u03C6\u03AE \u03BC\u03B5 \u03C4\u03B9\u03C2 \u03C5\u03C0\u03CC\u03BB\u03BF\u03B9\u03C0\u03B5\u03C2 \u03B5\u03BA\u03B4\u03B7\u03BB\u03CE\u03C3\u03B5\u03B9\u03C2...",
        "importEventsError_msg": "\u03BF\u03B9 {amount} \u03B1\u03C0\u03BF \u03C4\u03B9\u03C2 {total} \u03B5\u03BA\u03B4\u03B7\u03BB\u03CE\u03C3\u03B5\u03B9\u03C2, \u03B4\u03B5\u03BD \u03BC\u03C0\u03CC\u03C1\u03B5\u03C3\u03B1\u03BD \u03BD\u03B1 \u03B5\u03B9\u03C3\u03B1\u03C7\u03B8\u03BF\u03CD\u03BD.",
        "importExport_action": "\u0395\u03B9\u03C3\u03B1\u03B3\u03C9\u03B3\u03AE/\u03B5\u03BE\u03B1\u03B3\u03C9\u03B3\u03AE",
        "importInvalidDatesInEvent_msg": "{amount} \u03B1\u03C0\u03CC {total} \u03C3\u03C5\u03BC\u03B2\u03AC\u03BD\u03C4\u03B1 \u03C0\u03B5\u03C1\u03B9\u03AD\u03C7\u03BF\u03C5\u03BD \u03BC\u03B7-\u03AD\u03B3\u03BA\u03C5\u03C1\u03B5\u03C2 \u03B7\u03BC\u03B5\u03C1\u03BF\u03BC\u03B7\u03BD\u03AF\u03B5\u03C2 \u03BA\u03B1\u03B9 \u03B4\u03B5\u03BD \u03B8\u03B1 \u03B5\u03B9\u03C3\u03B1\u03C7\u03B8\u03BF\u03CD\u03BD.",
        "importPre1970StartInEvent_msg": "{amount} \u03B1\u03C0\u03CC {total} \u03C3\u03C5\u03BC\u03B2\u03AC\u03BD\u03C4\u03B1 \u03B1\u03C1\u03C7\u03AF\u03B6\u03BF\u03C5\u03BD \u03AE \u03BB\u03AE\u03B3\u03BF\u03C5\u03BD \u03C0\u03C1\u03B9\u03BD \u03C4\u03BF 1970 \u03BA\u03B1\u03B9 \u03B4\u03B5\u03BD \u03B8\u03B1 \u03B5\u03B9\u03C3\u03B1\u03C7\u03B8\u03BF\u03CD\u03BD.",
        "importReadFileError_msg": "\u0394\u03C5\u03C3\u03C4\u03C5\u03C7\u03CE\u03C2, \u03C4\u03BF \u03B1\u03C1\u03C7\u03B5\u03AF\u03BF {filename} \u03B4\u03B5\u03BD \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B1\u03BD\u03B1\u03B3\u03BD\u03CE\u03C3\u03B9\u03BC\u03BF.",
