        "open_action": "\u0386\u03BD\u03BF\u03B9\u03B3\u03BC\u03B1",
        "operationStillActive_msg": "\u0391\u03C5\u03C4\u03AE \u03B7 \u03BB\u03B5\u03B9\u03C4\u03BF\u03C5\u03C1\u03B3\u03AF\u03B1 \u03B4\u03B5\u03BD \u03BC\u03C0\u03BF\u03C1\u03B5\u03AF \u03BD\u03B1 \u03B5\u03BA\u03C4\u03B5\u03BB\u03B5\u03C3\u03C4\u03B5\u03AF \u03B1\u03C5\u03C4\u03AE\u03BD \u03C4\u03B7 \u03C3\u03C4\u03B9\u03B3\u03BC\u03AE, \u03B5\u03C0\u03B5\u03B9\u03B4\u03AE \u03B5\u03BE\u03B1\u03BA\u03BF\u03BB\u03BF\u03C5\u03B8\u03B5\u03AF \u03BD\u03B1 \u03B5\u03BA\u03C4\u03B5\u03BB\u03B5\u03AF\u03C4\u03B1\u03B9 \u03BC\u03B9\u03B1 \u03AC\u03BB\u03BB\u03B7 \u03BB\u03B5\u03B9\u03C4\u03BF\u03C5\u03C1\u03B3\u03AF\u03B1. \u03A0\u03C1\u03BF\u03C3\u03C0\u03B1\u03B8\u03AE\u03C3\u03C4\u03B5 \u03BE\u03B1\u03BD\u03AC \u03B1\u03C1\u03B3\u03CC\u03C4\u03B5\u03C1\u03B1.",
        "optionalValues_label": "\u0395\u03B8\u03B5\u03BB\u03BF\u03BD\u03C4\u03B9\u03BA\u03AD\u03C2 \u03C0\u03BB\u03B7\u03C1\u03BF\u03C6\u03BF\u03C1\u03AF\u03B5\u03C2",
        "options_action": "\u0395\u03C0\u03B9\u03BB\u03BF\u03B3\u03AD\u03C2",
        "orderAliasesConfirm_msg": "\u039C\u03C0\u03BF\u03C1\u03B5\u03AF\u03C4\u03B5 \u03BD\u03B1 \u03B5\u03C0\u03B9\u03BB\u03AD\u03BE\u03B5\u03C4\u03B5 \u03AD\u03BD\u03B1 \u03BC\u03B5\u03B3\u03B1\u03BB\u03CD\u03C4\u03B5\u03C1\u03BF \u03C0\u03B1\u03BA\u03AD\u03C4\u03BF \u03C8\u03B5\u03C5\u03B4\u03C9\u03BD\u03CD\u03BC\u03C9\u03BD \u03B3\u03B9\u03B1 \u03BD\u03B1 \u03BA\u03B1\u03C4\u03B1\u03C7\u03C9\u03C1\u03AE\u03C3\u03B5\u03C4\u03B5 \u03C0\u03B5\u03C1\u03B9\u03C3\u03C3\u03CC\u03C4\u03B5\u03C1\u03B1 \u03C8\u03B5\u03C5\u03B4\u03CE\u03BD\u03C5\u03BC\u03B1.",
        "orderProcessingAgreementInfo_msg": "\u03A3\u03C5\u03BC\u03C6\u03C9\u03BD\u03B1 \u03BC\u03B5 \u03C4\u03BF\u03BD \u03B5\u03C5\u03C1\u03C9\u03C0\u03B1\u03CA\u03BA\u03CC \u039A\u03B1\u03BD\u03BF\u03BD\u03B9\u03C3\u03BC\u03CC \u03A0\u03C1\u03BF\u03C3\u03C9\u03C0\u03B9\u03BA\u03CE\u03BD \u0394\u03B5\u03B4\u03BF\u03BC\u03AD\u03BD\u03C9\u03BD \u03B5\u03C4\u03B1\u03B9\u03C1\u03B9\u03BA\u03BF\u03AF \u03C0\u03B5\u03BB\u03AC\u03C4\u03B5\u03C2 \u03B5\u03AF\u03BD\u03B1\u03B9 \u03C5\u03C0\u03CC\u03C7\u03C1\u03B5\u03BF\u03B9 \u03BA\u03B1\u03C4\u03AC\u03B8\u03B5\u03C3\u03B7\u03C2 \u03C3\u03C5\u03BC\u03C6\u03C9\u03BD\u03B7\u03C4\u03B9\u03BA\u03BF\u03CD \u03BC\u03B5 \u03B5\u03BC\u03AC\u03C2.",
        "orderProcessingAgreement_label": "\u03A3\u03CD\u03BC\u03B2\u03B1\u03C3\u03B7 \u03B5\u03C0\u03B5\u03BE\u03B5\u03C1\u03B3\u03B1\u03C3\u03AF\u03B1\u03C2 \u03C0\u03B1\u03C1\u03B1\u03B3\u03B3\u03B5\u03BB\u03B9\u03CE\u03BD ",
        "ordertItNow_msg": "\u0398\u03AD\u03BB\u03B5\u03C4\u03B5 \u03BD\u03B1 \u03C0\u03B1\u03C1\u03B1\u03B3\u03B3\u03B5\u03AF\u03BB\u03B5\u03C4\u03B5 \u03C4\u03B7 \u03B4\u03C5\u03BD\u03B1\u03C4\u03CC\u03C4\u03B7\u03C4\u03B1 \u03C4\u03CE\u03C1\u03B1;",
        "order_action": "\u03A0\u03B1\u03C1\u03B1\u03B3\u03B3\u03B5\u03BB\u03AF\u03B1 ",
