        "businessDeletionWarning_msg": "\u0642\u0627\u0628\u0644\u06CC\u062A \u062A\u062C\u0627\u0631\u06CC \u0628\u0631\u0627\u06CC \u062A\u0645\u0627\u0645\u06CC \u06A9\u0627\u0631\u0628\u0631\u0627\u0646\u060C \u0647\u0645 \u0627\u06A9\u0646\u0648\u0646 \u063A\u06CC\u0631\u0641\u0639\u0627\u0644 \u062E\u0648\u0627\u0647\u062F \u0634\u062F. \u067E\u0627\u0633\u062E\u200C\u06AF\u0648\u06CC\u06CC \u062E\u0648\u062F\u06A9\u0627\u0631 \u0648 \u062F\u0639\u0648\u062A\u200C\u0646\u0627\u0645\u0647 \u0647\u0627\u06CC \u062A\u0642\u0648\u06CC\u0645 \u0627\u0632 \u06A9\u0627\u0631 \u062E\u0648\u0627\u0647\u0646\u062F \u0627\u0641\u062A\u0627\u062F. \u0641\u0642\u0637 \u06CC\u06A9 \u062F\u0627\u0645\u0646\u0647 \u0627\u06CC\u0645\u06CC\u0644 \u0634\u062E\u0635\u06CC \u0645\u062C\u0627\u0632 \u062E\u0648\u0627\u0647\u062F \u0628\u0648\u062F.",
        "businessFeatureRequiredGeneral_msg": "\u0628\u0631\u0627\u06CC \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0627\u0632 \u0627\u06CC\u0646 \u0639\u0645\u0644\u06A9\u0631\u062F \u0628\u0627\u06CC\u062F \u0642\u0627\u0628\u0644\u06CC\u062A \u062A\u062C\u0627\u0631\u06CC \u0631\u0627 \u0633\u0641\u0627\u0631\u0634 \u062F\u0647\u06CC\u062F.",
        "businessFeatureRequiredInvite_msg": "\u0628\u0631\u0627\u06CC \u0641\u0631\u0633\u062A\u0627\u062F\u0646 \u062F\u0639\u0648\u062A\u200C\u0646\u0627\u0645\u0647 \u0631\u0648\u06CC\u062F\u0627\u062F \u0634\u0645\u0627 \u0628\u0627\u06CC\u062F \u0642\u0627\u0628\u0644\u06CC\u062A \u062A\u062C\u0627\u0631\u06CC \u0631\u0627 \u0633\u0641\u0627\u0631\u0634 \u062F\u0647\u06CC\u062F.",
