        "differentSecurityKeyDomain_msg": "\u06A9\u0644\u06CC\u062F \u0627\u0645\u0646\u06CC\u062A\u06CC \u0634\u0645\u0627 \u0628\u0631\u0627\u06CC \u0627\u06CC\u0646 \u062F\u0627\u0645\u0646\u0647 \u062B\u0628\u062A \u0646\u0634\u062F\u0647 \u0627\u0633\u062A. \u0644\u0637\u0641\u0627\u064B \u0628\u0647 {domain} \u0648\u0627\u0631\u062F \u0634\u0648\u06CC\u062F.",
        "disallowExternalContent_action": "\u0627\u0646\u0633\u062F\u0627\u062F \u0645\u062D\u062A\u0648\u0627\u06CC \u062E\u0627\u0631\u062C\u06CC",
