        "dnsRecordValueOrPointsTo_label": "\u0627\u0631\u0632\u0634/\u0627\u0645\u062A\u06CC\u0627\u0632 \u0628\u0647",
        "domainSetup_title": "\u062A\u0646\u0638\u06CC\u0645 \u062F\u0627\u0645\u0646\u0647 \u062F\u0644\u062E\u0648\u0627\u0647",
        "domainStillHasContactForms_msg": "\u0627\u0645\u06A9\u0627\u0646 \u063A\u06CC\u0631\u0641\u0639\u0627\u0644 \u06A9\u0631\u062F\u0646 {domain} \u0648\u062C\u0648\u062F \u0646\u062F\u0627\u0631\u062F \u0632\u06CC\u0631\u0627 \u0647\u0645\u0686\u0646\u0627\u0646 \u0641\u0631\u0645\u200C\u0647\u0627\u06CC \u062A\u0645\u0627\u0633 \u0641\u0639\u0627\u0644\u06CC \u0628\u0631 \u0631\u0648\u06CC \u062F\u0627\u0645\u0646\u0647 \u0644\u06CC\u0633\u062A\u200C\u0633\u0641\u06CC\u062F \u0648\u062C\u0648\u062F \u062F\u0627\u0631\u0646\u062F. \u0644\u0637\u0641\u0627 \u0627\u0628\u062A\u062F\u0627 \u0641\u0631\u0645\u200C\u0647\u0627\u06CC \u062A\u0645\u0627\u0633 \u0631\u0627 \u067E\u0627\u06A9 \u06A9\u0631\u062F\u0647 \u0633\u067E\u0633 \u0646\u0633\u0628\u062A \u0628\u0647 \u063A\u06CC\u0631\u0641\u0639\u0627\u0644 \u06A9\u0631\u062F\u0646 {domain} \u0627\u0642\u062F\u0627\u0645 \u06A9\u0646\u06CC\u062F.",
