        "giftCardUpdateError_msg": "\u0646\u0627\u062A\u0648\u0627\u0646 \u0627\u0632 \u0628\u0647 \u0631\u0648\u0632\u0631\u0633\u0627\u0646\u06CC \u06A9\u0627\u0631\u062A \u0647\u062F\u06CC\u0647.",
        "giftCardUpgradeNotify_msg": "\u062D\u0633\u0627\u0628 \u0634\u0645\u0627 \u0628\u0647 \u0637\u0648\u0631 \u062E\u0648\u062F\u06A9\u0627\u0631 \u0628\u0647 \u062D\u0633\u0627\u0628 \u0648\u06CC\u0698\u0647 \u0628\u0627 \u0627\u0634\u062A\u0631\u0627\u06A9 \u0633\u0627\u0644\u06CC\u0627\u0646\u0647 \u0627\u0631\u062A\u0642\u0627 \u062E\u0648\u0627\u0647\u062F \u06CC\u0627\u0641\u062A. \u0647\u0632\u06CC\u0646\u0647 \u0633\u0627\u0644 \u0627\u0648\u0644 ({price}) \u0627\u0632\u0645\u0648\u062C\u0648\u062F\u06CC \u06A9\u0627\u0631\u062A \u0647\u062F\u06CC\u0647\u200C \u0634\u0645\u0627 \u06A9\u0645 \u062E\u0648\u0627\u0647\u062F \u0634\u062F \u0648 \u0645\u0627\u0628\u0642\u06CC \u0645\u0648\u062C\u0648\u062F\u06CC \u06A9\u0627\u0631\u062A ({credit})\u060C \u0628\u0647 \u0639\u0646\u0648\u0627\u0646 \u0627\u0639\u062A\u0628\u0627\u0631 \u0628\u0647 \u062D\u0633\u0627\u0628 \u0634\u0645\u0627 \u0645\u0646\u0638\u0648\u0631 \u062E\u0648\u0627\u0647\u062F \u0634\u062F.",
