        "globalSettings_label": "\u062A\u0646\u0638\u06CC\u0645\u0627\u062A \u0633\u0631\u0627\u0633\u0631\u06CC",
        "goPremium_msg": "\u0628\u0647 \u0639\u0646\u0648\u0627\u0646 \u06CC\u06A9 \u06A9\u0627\u0631\u0628\u0631 \u0628\u0627 \u0646\u0633\u062E\u0647\u0654 \u067E\u06CC\u0634\u0631\u0641\u062A\u0647 \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u06CC\u062F \u0641\u06CC\u0644\u062A\u0631\u0647\u0627\u06CC \u062C\u0633\u062A\u062C\u0648\u06CC \u062E\u0648\u062F\u062A\u0627\u0646 \u0631\u0627 \u062F\u0631 \u0641\u0647\u0631\u0633\u062A \u0633\u0645\u062A \u0686\u067E \u062A\u0646\u0638\u06CC\u0645 \u06A9\u0646\u06CC\u062F.",
