        "importEventExistingUid_msg": "\u062A\u0639\u062F\u0627\u062F {amount} \u062A\u0627 \u0627\u0632 {total} \u0631\u0648\u06CC\u062F\u0627\u062F \u0647\u0645\u06CC\u0646 \u062D\u0627\u0644\u0627 \u0647\u0645 \u0648\u062C\u0648\u062F \u062F\u0627\u0631\u062F \u0648 \u0645\u062C\u062F\u062F\u0627 \u062B\u0628\u062A \u0646\u062E\u0648\u0627\u0647\u0646\u062F \u0634\u062F. \u0641\u0631\u0622\u06CC\u0646\u062F \u062B\u0628\u062A \u0628\u0631\u0627\u06CC \u0645\u0627\u0628\u0642\u06CC \u0631\u0648\u06CC\u062F\u0627\u062F\u0647\u0627 \u0627\u062F\u0627\u0645\u0647 \u062E\u0648\u0627\u062F \u06CC\u0627\u0641\u062A...",
        "importEventsError_msg": "\u0648\u0627\u0631\u062F \u06A9\u0631\u062F\u0646 {amount} \u062A\u0627 \u0627\u0632 {total} \u0631\u0648\u06CC\u062F\u0627\u062F \u0645\u0645\u06A9\u0646 \u0646\u0634\u062F.",
        "importExport_action": "\u0648\u0627\u0631\u062F \u06A9\u0631\u062F\u0646/\u0635\u0627\u062F\u0631 \u06A9\u0631\u062F\u0646",
        "importReadFileError_msg": "\u0628\u0627 \u0639\u0631\u0636 \u067E\u0648\u0632\u0634 \u060C \u0641\u0627\u06CC\u0644{filename} \u0642\u0627\u0628\u0644 \u062E\u0648\u0627\u0646\u062F\u0646 \u0646\u06CC\u0633\u062A.",
