        "outdatedClientWarningMailSubject_msg": "\u0644\u0637\u0641\u0627 \u062A\u0648\u062A\u0627\u0646\u0648\u062A\u0627 \u0631\u0627 \u0628\u0647\u200C \u0631\u0648\u0632\u0631\u0633\u0627\u0646\u06CC \u06A9\u0646\u06CC\u062F",
        "outdatedClient_msg": "\u0644\u0637\u0641\u0627 \u062A\u0648\u062A\u0627\u0646\u0648\u062A\u0627 \u0631\u0627 \u0628\u0647 \u0631\u0648\u0632 \u06A9\u0646\u06CC\u062F. \u0646\u0633\u062E\u0647  \u0646\u0635\u0628 \u0634\u062F\u0647 \u062D\u0627\u0636\u0631 \u062E\u06CC\u0644\u06CC \u0642\u062F\u06CC\u0645\u06CC\u200C\u0633\u062A \u0648 \u062F\u06CC\u06AF\u0631 \u067E\u0634\u062A\u06CC\u0628\u0627\u0646\u06CC \u0646\u0645\u06CC\u200C\u0634\u0648\u062F.",
        "outlookInvoiceMailBodyAutomatic_msg": "\u067E\u06CC\u0648\u0633\u062A \u0628\u0647 \u0627\u06CC\u0646 \u0627\u06CC\u0645\u06CC\u0644\u060C \u06CC\u06A9 \u0635\u0648\u0631\u062A\u062D\u0633\u0627\u0628 \u062C\u062F\u06CC\u062F \u0628\u0647 \u0634\u0645\u0627\u0631\u0647\u200C\u06CC {1} \u0628\u0631\u0627\u06CC \u0634\u0645\u0627 \u062F\u0631 \u062F\u0633\u062A\u0631\u0633 \u0627\u0633\u062A. \u062C\u0645\u0639 \u06A9\u0644 \u0628\u0647 \u0637\u0648\u0631 \u062E\u0648\u062F\u06A9\u0627\u0631 \u0627\u0632 \u062D\u0633\u0627\u0628 \u0634\u0645\u0627 \u0628\u0631\u062F\u0627 \u0634\u062A \u062E\u0648\u0627\u0647\u062F \u0634\u062F. \u0634\u0645\u0627 \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u06CC\u062F \u0647\u0645\u0647\u200C\u06CC \u0635\u0648\u0631\u062A\u062D\u0633\u0627\u0628\u200C\u0647\u0627\u06CC \u062E\u0648\u062F \u0631\u0627 \u0627\u0632 \u0627\u06CC\u0646\u062C\u0627 \u0645\u0634\u0627\u0647\u062F\u0647 \u06A9\u0646\u06CC\u062F {2}",
        "outlookInvoiceMailBodyOnAccount_msg": "\u06CC\u06A9 \u0635\u0648\u0631\u062A\u062D\u0633\u0627\u0628 \u062C\u062F\u06CC\u062F \u0628\u0647 \u0634\u0645\u0627\u0631\u0647\u0654 {1} \u0628\u0631\u0627\u06CC \u0634\u0645\u0627 \u062D\u0627\u0636\u0631 \u0627\u0633\u062A \u0648 \u0628\u0647 \u0627\u06CC\u0646 \u0627\u06CC\u0645\u06CC\u0644 \u067E\u06CC\u0648\u0633\u062A \u0634\u062F\u0647 \u0627\u0633\u062A. \u0633\u0631\u0631\u0633\u06CC\u062F \u067E\u0631\u062F\u0627\u062E\u062A \u06F7 \u0631\u0648\u0632 \u067E\u0633 \u0627\u0632 \u062A\u0627\u0631\u06CC\u062E \u0635\u0648\u0631\u062A\u062D\u0633\u0627\u0628 \u0627\u0633\u062A. \u0647\u0645\u0686\u0646\u06CC\u0646 \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u06CC\u062F \u0647\u0645\u0647\u0654 \u0635\u0648\u0631\u062A\u062D\u0633\u0627\u0628\u200C\u0647\u0627\u06CC \u062E\u0648\u062F \u0631\u0627 \u062F\u0631\u0627\u06CC\u0646\u062C\u0627  {2}  \u0645\u0634\u0627\u0647\u062F\u0647 \u06A9\u0646\u06CC\u062F.",
        "outOfOfficeDefaultSubject_msg": "\u062E\u0627\u0631\u062C \u0627\u0632 \u062F\u0641\u062A\u0631 \u06A9\u0627\u0631 \u0647\u0633\u062A\u0645",
        "outOfOfficeDefault_msg": "\u0633\u0644\u0627\u0645\u060C\n<br>\n<br>\u0627\u0632 \u0627\u06CC\u0645\u06CC\u0644\u062A \u0645\u0645\u0646\u0648\u0646\u0645. \u0645\u0646 \u062E\u0627\u0631\u062C \u0627\u0632 \u062F\u0641\u062A\u0631 \u06A9\u0627\u0631 \u0647\u0633\u062A\u0645 \u0648 \u0628\u0647 \u0632\u0648\u062F\u06CC \u0628\u0627\u0632 \u062E\u0648\u0627\u0647\u0645 \u06AF\u0634\u062A. \u062A\u0627 \u0622\u0646 \u0632\u0645\u0627\u0646\u060C \u062F\u0633\u062A\u0631\u0633\u06CC \u0645\u062D\u062F\u0648\u062F\u06CC \u0628\u0647 \u062D\u0633\u0627\u0628 \u0627\u06CC\u0645\u06CC\u0644\u0645 \u062E\u0648\u0627\u0647\u0645 \u062F\u0627\u0634\u062A.\n<br>\n<br>\u0628\u0627 \u0627\u062D\u062A\u0631\u0627\u0645",
        "outOfOfficeEveryone_msg": "\u0628\u0647 \u0647\u0645\u0647",
        "outOfOfficeExternal_msg": "\u062E\u0627\u0631\u062C \u0627\u0632 \u0633\u0627\u0632\u0645\u0627\u0646 \u0634\u0645\u0627",
        "outOfOfficeInternal_msg": "\u062F\u0631\u0648\u0646 \u0633\u0627\u0632\u0645\u0627\u0646 \u0634\u0645\u0627",
        "outOfOfficeMessageInvalid_msg": "\u0645\u0648\u0636\u0648\u0639 \u0648/\u06CC\u0627 \u067E\u06CC\u0627\u0645 \u0646\u0627\u0645\u0639\u062A\u0628\u0631 \u0627\u0633\u062A.\n\u062E\u0627\u0644\u06CC \u0645\u0627\u0646\u062F\u0646 \u0645\u0648\u0636\u0648\u0639 \u0648 \u067E\u06CC\u0627\u0645 \u0645\u062C\u0627\u0632 \u0646\u06CC\u0633\u062A.\n\u0628\u06CC\u0634\u062A\u0631\u06CC\u0646 \u062A\u0639\u062F\u0627\u062F \u06A9\u0627\u0631\u0627\u06A9\u062A\u0631 \u0645\u062C\u0627\u0632 \u0628\u0631\u0627\u06CC \u0645\u0648\u0636\u0648\u0639: \u06F1\u06F2\u06F8\u06A9\u0627\u0631\u0627\u06A9\u062A\u0631.\n\u0628\u06CC\u0634\u062A\u0631\u06CC\u0646 \u062D\u062C\u0645 \u0645\u062C\u0627\u0632 \u0628\u0631\u0627\u06CC \u067E\u06CC\u0627\u0645: \u06F2\u06F0 \u06A9\u06CC\u0644\u0648 \u0628\u0627\u06CC\u062A.",
        "outOfOfficeNotification_title": "\u067E\u0627\u0633\u062E\u200C\u06AF\u0648\u06CC \u062E\u0648\u062F\u06A9\u0627\u0631",
        "outOfOfficeRecipientsEveryoneHelp_label": "\u0627\u0639\u0644\u0627\u0646\u200C\u0647\u0627\u06CC \u0627\u0637\u0644\u0627\u0639\u200C\u0631\u0633\u0627\u0646\u06CC \u0628\u0647 \u0647\u0645\u0647 \u0641\u0631\u0633\u062A\u0627\u062F\u0647 \u062E\u0648\u0627\u0647\u0646\u062F \u0634\u062F.",
        "outOfOfficeRecipientsInternalExternalHelp_label": "\u0627\u0639\u0644\u0627\u0646\u200C\u0647\u0627\u06CC \u0645\u062C\u0632\u0627 \u0628\u0631\u0627\u06CC \u062A\u0645\u0627\u0645\u06CC \u06AF\u06CC\u0631\u0646\u062F\u06AF\u0627\u0646 \u062F\u0627\u062E\u0644\u06CC \u0648 \u062E\u0627\u0631\u062C\u06CC \u0633\u0627\u0632\u0645\u0627\u0646 \u0634\u0645\u0627 \u0641\u0631\u0633\u062A\u0627\u062F\u0647 \u0645\u06CC\u200C\u0634\u0648\u0646\u062F.",
        "outOfOfficeRecipientsInternalOnlyHelp_label": "\u0627\u0639\u0644\u0627\u0646\u200C\u0647\u0627\u06CC \u0627\u0637\u0644\u0627\u0639\u200C\u0631\u0633\u0627\u0646\u06CC \u062A\u0646\u0647\u0627 \u0628\u0647 \u0627\u0641\u0631\u0627\u062F \u062F\u0631\u0648\u0646 \u0633\u0627\u0632\u0645\u0627\u0646 \u0634\u0645\u0627 \u0641\u0631\u0633\u062A\u0627\u062F\u0647 \u062E\u0648\u0627\u0647\u0646\u062F \u0634\u062F.",
        "outOfOfficeRecipients_label": "\u06AF\u06CC\u0631\u0646\u062F\u06AF\u0627\u0646 \u0627\u0639\u0644\u0627\u0646 \u0627\u0637\u0644\u0627\u0639\u200C\u0631\u0633\u0627\u0646\u06CC",
        "outOfOfficeReminder_label": "\u067E\u0627\u0633\u062E\u200C\u06AF\u0648\u06CC\u06CC \u062E\u0648\u062F\u06A9\u0627\u0631 \u0641\u0639\u0627\u0644 \u0634\u062F\u0647 \u0627\u0633\u062A.",
        "outOfOfficeTimeRangeHelp_msg": "\u0628\u0631\u0627\u06CC \u062A\u0639\u06CC\u06CC\u0646 \u0631\u0648\u0632\u060C \u0627\u0646\u062A\u062E\u0627\u0628 \u06A9\u0646\u06CC\u062F.",
