        "shareCalendarDeclineEmailSubject_msg": "\u062F\u0639\u0648\u062A \u062A\u0642\u0648\u06CC\u0645 \u0631\u062F \u0634\u062F",
        "shareCalendarInvitationEmailBody_msg": '\u0633\u0644\u0627\u0645 \u060C <br/>  \u062F\u0639\u0648\u062A \u06A9\u0646\u0646\u062F\u0647{inviter} \u0627\u0632 \u0634\u0645\u0627 \u062F\u0639\u0648\u062A \u06A9\u0631\u062F\u0647 \u0627\u0633\u062A \u062A\u0627 \u062F\u0631 \u062A\u0642\u0648\u06CC\u0645 "{calendarName} " \u0634\u0631\u06A9\u062A \u06A9\u0646\u06CC\u062F. \u0645\u06CC \u062A\u0648\u0627\u0646\u06CC\u062F \u062C\u0632\u0626\u06CC\u0627\u062A \u0627\u06CC\u0646 \u062F\u0639\u0648\u062A \u0631\u0627 \u062F\u0631 \u0646\u0645\u0627\u06CC \u062A\u0642\u0648\u06CC\u0645 \u0628\u0631\u0631\u0633\u06CC \u06A9\u0646\u06CC\u062F \u062A\u0627 \u0622\u0646 \u0631\u0627 \u0628\u067E\u0630\u06CC\u0631\u06CC\u062F \u06CC\u0627 \u0631\u062F \u06A9\u0646\u06CC\u062F. <br/> <br/> \u0627\u06CC\u0646 \u06CC\u06A9 \u067E\u06CC\u0627\u0645 \u062E\u0648\u062F\u06A9\u0627\u0631 \u0627\u0633\u062A.',
        "shareCalendarInvitationEmailSubject_msg": "\u062F\u0639\u0648\u062A \u0628\u0647 \u0634\u0631\u06A9\u062A \u062F\u0631 \u062A\u0642\u0648\u06CC\u0645",
        "shareCalendarWarningAliases_msg": "\u0622\u0646\u0647\u0627 \u0647\u0645\u0686\u0646\u06CC\u0646 \u0645\u06CC \u062A\u0648\u0627\u0646\u0646\u062F \u0646\u0627\u0645 \u0647\u0627\u06CC \u0645\u0633\u062A\u0639\u0627\u0631 \u0627\u06CC\u0645\u06CC\u0644 \u0645\u0631\u062A\u0628\u0637 \u0628\u0627 \u0635\u0646\u062F\u0648\u0642 \u067E\u0633\u062A\u06CC \u0634\u0645\u0627 \u0631\u0627 \u0645\u0634\u0627\u0647\u062F\u0647 \u06A9\u0646\u0646\u062F.",
