        "confirmDeactivateWhitelabelDomain_msg": "\u05D4\u05D0\u05DD \u05D0\u05EA\u05DD \u05D1\u05D8\u05D5\u05D7\u05D9\u05DD \u05E9\u05D1\u05E8\u05E6\u05D5\u05E0\u05DB\u05DD \u05DC\u05D1\u05D8\u05DC \u05D0\u05EA \u05D4\u05DB\u05E0\u05D9\u05E1\u05D4 \u05DC-Tutanota \u05E2\u05D1\u05D5\u05E8 \u05D4\u05D3\u05D5\u05DE\u05D9\u05D9\u05DF \u05E9\u05DC\u05DB\u05DD \u05D5\u05DC\u05DE\u05D7\u05D5\u05E7 \u05D0\u05EA \u05D0\u05D9\u05E9\u05D5\u05E8 \u05D4-SSL, \u05D4\u05DC\u05D5\u05D2\u05D5 \u05D5\u05D4\u05E6\u05D1\u05E2\u05D9\u05DD \u05D4\u05DE\u05D5\u05EA\u05D0\u05DE\u05D9\u05DD?",
        "confirmDeleteContactForm_msg": "\u05D4\u05D0\u05DD \u05D0\u05EA\u05DD \u05D1\u05D8\u05D5\u05D7\u05D9\u05DD \u05E9\u05D1\u05E8\u05E6\u05D5\u05E0\u05DB\u05DD \u05DC\u05DE\u05D7\u05D5\u05E7 \u05D8\u05D5\u05E4\u05E1 \u05D0\u05D9\u05E9 \u05E7\u05E9\u05E8 \u05D6\u05D4?",
        "confirmDeleteFinallyCustomFolder_msg": `\u05D4\u05D0\u05DD \u05D0\u05EA\u05DD \u05D1\u05D8\u05D5\u05D7\u05D9\u05DD \u05E9\u05D1\u05E8\u05E6\u05D5\u05E0\u05DB\u05DD \u05DC\u05DE\u05D7\u05D5\u05E7 \u05D0\u05EA \u05D4\u05EA\u05D9\u05E7\u05D9\u05D4 '{1}' \u05D5\u05DB\u05DC \u05D4\u05D3\u05D5\u05D0"\u05DC \u05E9\u05D1\u05D4? \u05DB\u05EA\u05DC\u05D5\u05EA \u05D1\u05DB\u05DE\u05D5\u05EA \u05D4\u05D4\u05D5\u05D3\u05E2\u05D5\u05EA, \u05EA\u05D4\u05DC\u05D9\u05DA \u05D6\u05D4 \u05E2\u05E9\u05D5\u05D9 \u05DC\u05D4\u05D9\u05DE\u05E9\u05DA \u05D6\u05DE\u05DF \u05E8\u05D1 \u05D5\u05D9\u05EA\u05D1\u05E6\u05E2 \u05D1\u05E8\u05E7\u05E2.`,
        "confirmDeleteFinallySystemFolder_msg": `\u05D4\u05D0\u05DD \u05D0\u05EA\u05DD \u05D1\u05D8\u05D5\u05D7\u05D9\u05DD \u05E9\u05D1\u05E8\u05E6\u05D5\u05E0\u05DB\u05DD \u05DC\u05DE\u05D7\u05D5\u05E7 \u05DC\u05E6\u05DE\u05D9\u05EA\u05D5\u05EA \u05D0\u05EA \u05DB\u05DC \u05D4\u05D5\u05D3\u05E2\u05D5\u05EA \u05D4\u05D3\u05D5\u05D0"\u05DC \u05DE\u05EA\u05D9\u05E7\u05D9\u05D9\u05EA \u05D4\u05DE\u05E2\u05E8\u05DB\u05EA '{1}'? \u05DB\u05EA\u05DC\u05D5\u05EA \u05D1\u05DB\u05DE\u05D5\u05EA \u05D4\u05D4\u05D5\u05D3\u05E2\u05D5\u05EA, \u05EA\u05D4\u05DC\u05D9\u05DA \u05D6\u05D4 \u05E2\u05E9\u05D5\u05D9 \u05DC\u05D4\u05D9\u05DE\u05E9\u05DA \u05D6\u05DE\u05DF \u05E8\u05D1 \u05D5\u05D9\u05D1\u05D5\u05E6\u05E2 \u05D1\u05E8\u05E7\u05E2. `,
        "confirmDeleteSecondFactor_msg": "\u05D4\u05D0\u05DD \u05D0\u05EA\u05DD \u05D1\u05D8\u05D5\u05D7\u05D9\u05DD \u05E9\u05D1\u05E8\u05E6\u05D5\u05E0\u05DB\u05DD \u05DC\u05DE\u05D7\u05D5\u05E7 \u05D0\u05EA \u05D4\u05D2\u05D5\u05E8\u05DD \u05D4\u05DE\u05E9\u05E0\u05D9 \u05D4\u05D6\u05D4?",
        "confirmFreeAccount_label": "\u05D0\u05D9\u05E9\u05D5\u05E8 \u05D7\u05E9\u05D1\u05D5\u05DF \u05D7\u05D9\u05E0\u05DE\u05D9",
        "confirmNoOtherFreeAccount_msg": "\u05D0\u05D9\u05DF \u05D1\u05D1\u05E2\u05DC\u05D5\u05EA\u05D9 \u05D7\u05E9\u05D1\u05D5\u05E0\u05D5\u05EA \u05D7\u05D9\u05E0\u05DE\u05D9\u05D9\u05DD \u05E0\u05D5\u05E1\u05E4\u05D9\u05DD.",
