        "undo_action": "\u05D1\u05D9\u05D8\u05D5\u05DC",
        "unknownError_msg": "\u05D8\u05E2\u05D5\u05EA \u05DC\u05D0 \u05E6\u05E4\u05D5\u05D9\u05D4 \u05E7\u05E8\u05EA\u05D4.\u05D0\u05E0\u05D0 \u05E0\u05E1\u05D4 \u05DE\u05D0\u05D5\u05D7\u05E8 \u05D9\u05D5\u05EA\u05E8.",
        "unlimited_label": "\u05DC\u05DC\u05D0 \u05D4\u05D2\u05D1\u05DC\u05D4",
        "unprocessedBookings_msg": "\u05D9\u05E9 \u05DC\u05DA \u05DB\u05DE\u05D4 \u05D4\u05D6\u05DE\u05E0\u05D5\u05EA \u05E9\u05DC\u05D0 \u05E2\u05D5\u05D1\u05D3\u05D5 \u05E2\u05DD \u05E9\u05D5\u05D5\u05D9 \u05DB\u05D5\u05DC\u05DC \u05E9\u05DC {amount}. \u05E1\u05DB\u05D5\u05DD \u05D6\u05D4 \u05D9\u05E0\u05D5\u05DB\u05D4 \u05DE\u05D4\u05D9\u05EA\u05E8\u05D4 \u05E9\u05DC\u05DA \u05D5 / \u05D0\u05D5 \u05DE\u05E9\u05D9\u05D8\u05EA \u05D4\u05EA\u05E9\u05DC\u05D5\u05DD \u05E9\u05D1\u05D7\u05E8\u05EA \u05D1\u05D7\u05E9\u05D1\u05D5\u05E0\u05D9\u05EA \u05D4\u05D1\u05D0\u05D4.",
        "unrecognizedU2fDevice_msg": "\u05DE\u05E4\u05EA\u05D7 \u05D4\u05D0\u05D1\u05D8\u05D7\u05D4 \u05E9\u05DC\u05DB\u05DD \u05DC\u05D0 \u05D6\u05D5\u05D4\u05D4.",
        "unregistered_label": "\u05DC\u05D0 \u05E8\u05E9\u05D5\u05DD",
        "unsubscribeConfirm_msg": "\u05D0\u05EA\u05DD \u05D1\u05D8\u05D5\u05D7\u05D9\u05DD \u05E9\u05D1\u05E8\u05E6\u05D5\u05E0\u05DB\u05DD \u05DC\u05D1\u05D8\u05DC \u05D0\u05EA \u05D4\u05D4\u05E8\u05E9\u05DE\u05D4? \u05D7\u05E9\u05D1\u05D5\u05E0\u05DB\u05DD \u05D9\u05D4\u05E4\u05D5\u05DA \u05DC\u05D7\u05D9\u05E0\u05DE\u05D9 \u05D5\u05D4\u05D0\u05E4\u05E9\u05E8\u05D5\u05D9\u05D5\u05EA \u05D1\u05EA\u05E9\u05DC\u05D5\u05DD \u05D9\u05D0\u05D1\u05D3\u05D5 \u05DE\u05D9\u05D9\u05D3. \u05E9\u05D9\u05DE\u05D5 \u05DC\u05D1 \u05E9\u05D7\u05E9\u05D1\u05D5\u05E0\u05D5\u05EA \u05D7\u05D9\u05E0\u05DE\u05D9\u05D9\u05DD \u05E9\u05DC\u05D0 \u05E9\u05D5\u05DE\u05E9\u05D5 \u05D1\u05DE\u05E9\u05DA \u05D9\u05D5\u05EA\u05E8 \u05DE\u05D7\u05E6\u05D9 \u05E9\u05E0\u05D4, \u05D9\u05D9\u05DE\u05D7\u05E7\u05D5.",
        "unsubscribeFailed_msg": "\u05D1\u05D9\u05D8\u05D5\u05DC \u05E8\u05E9\u05D9\u05DE\u05EA \u05EA\u05E4\u05D5\u05E6\u05D4 \u05D0\u05D5 \u05D9\u05D3\u05D9\u05E2\u05D5\u05DF \u05DC\u05D0 \u05D4\u05E6\u05DC\u05D9\u05D7.",
        "unsubscribeSuccessful_msg": "\u05D4\u05D4\u05E8\u05E9\u05DE\u05D4 \u05DC\u05E8\u05E9\u05D9\u05DE\u05EA \u05D4\u05D3\u05D9\u05D5\u05D5\u05E8 \u05D1\u05D5\u05D8\u05DC\u05D4 \u05D1\u05D4\u05E6\u05DC\u05D7\u05D4!",
        "unsubscribe_action": "\u05D1\u05D9\u05D8\u05D5\u05DC \u05DE\u05E0\u05D5\u05D9",
        "unsupportedBrowserOverlay_msg": "\u05D0\u05EA\u05DD \u05DE\u05E9\u05EA\u05DE\u05E9\u05D9\u05DD \u05D1\u05D3\u05E4\u05D3\u05E4\u05DF \u05E9\u05D0\u05D9\u05E0\u05D5 \u05E0\u05EA\u05DE\u05DA. \u05EA\u05D9\u05EA\u05DB\u05DF \u05D4\u05D2\u05D1\u05DC\u05D4 \u05E9\u05DC \u05E4\u05E2\u05D5\u05DC\u05D5\u05EA \u05DE\u05E1\u05D5\u05D9\u05D9\u05DE\u05D5\u05EA.",
        "unsupportedBrowser_msg": "\u05D4\u05D5! \u05D0\u05E0\u05D5 \u05DE\u05EA\u05E0\u05E6\u05DC\u05D9\u05DD. \u05DC\u05DE\u05E8\u05D1\u05D4 \u05D4\u05E6\u05E2\u05E8, \u05D4\u05D3\u05E4\u05D3\u05E4\u05DF \u05E9\u05DC\u05DB\u05DD \u05DC\u05D0 \u05E0\u05EA\u05DE\u05DA \u05D0\u05D5 \u05DE\u05D9\u05D5\u05E9\u05DF. \u05D0\u05E0\u05D0 \u05D4\u05E9\u05EA\u05DE\u05E9\u05D5 \u05D1\u05D2\u05E8\u05E1\u05D4 \u05D4\u05E2\u05D3\u05DB\u05E0\u05D9\u05EA \u05D1\u05D9\u05D5\u05EA\u05E8 \u05E9\u05DC \u05D0\u05D7\u05D3 \u05DE\u05D4\u05D3\u05E4\u05D3\u05E4\u05E0\u05D9\u05DD \u05D4\u05D1\u05D0\u05D9\u05DD:",
        "until_label": "\u05E2\u05D3",
        "updateAdminshipGlobalAdmin_msg": "\u05D0\u05D9\u05DF \u05D1\u05D0\u05E4\u05E9\u05E8\u05D5\u05EA\u05DB\u05DD \u05DC\u05E9\u05E0\u05D5\u05EA \u05D0\u05EA \u05D4\u05D4\u05E0\u05D4\u05DC\u05D4 \u05E9\u05DC \u05DE\u05E0\u05D4\u05DC \u05D2\u05DC\u05D5\u05D1\u05DC\u05D9.",
