        "defaultShareGiftCardBody_msg": "\n\u0928\u092E\u0938\u094D\u0924\u0947, \n\n\u092E\u0948\u0902\u0928\u0947 \u0906\u092A\u0915\u094B \u091F\u0942\u091F\u0928\u094B\u091F\u093E \u0915\u0947 \u0932\u093F\u090F \u090F\u0915 \u0909\u092A\u0939\u093E\u0930 \u0915\u093E\u0930\u094D\u0921 \u0916\u0930\u0940\u0926\u093E \u0939\u0948, \u0907\u0938 \u0932\u093F\u0902\u0915 \u0915\u093E \u0909\u092A\u092F\u094B\u0917 \u0907\u0938\u0947 \u0930\u093F\u0921\u0940\u092E \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0915\u0930\u0947\u0902! \n{link}\n \u092F\u0926\u093F \u0906\u092A\u0915\u0947 \u092A\u093E\u0938 \u0905\u092D\u0940 \u0924\u0915 \u0915\u094B\u0908 \u0916\u093E\u0924\u093E \u0928\u0939\u0940\u0902 \u0939\u0948, \u0924\u094B \u0906\u092A \u0938\u093E\u0907\u0928 \u0905\u092A \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0914\u0930 \u0905\u092A\u0928\u0940 \u0917\u094B\u092A\u0928\u0940\u092F\u0924\u093E \u0915\u094B \u092A\u0941\u0928\u0903 \u092A\u094D\u0930\u093E\u092A\u094D\u0924 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0932\u093F\u0902\u0915 \u0915\u093E \u0909\u092A\u092F\u094B\u0917 \u0915\u0930 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964\n\n\u0939\u0948\u092A\u094D\u092A\u0940 \u091B\u0941\u091F\u094D\u091F\u093F\u092F\u093E\u0901,\n{username}",
        "defaultShareGiftCardSubject_msg": "\u0906\u092A\u0915\u094B \u090F\u0915 \u0924\u0941\u0924\u093E\u0928\u094B\u091F\u093E \u0909\u092A\u0939\u093E\u0930 \u0915\u093E\u0930\u094D\u0921 \u092E\u093F\u0932\u093E \u0939\u0948!",
        "deleteAccountConfirm_msg": "\u0915\u094D\u092F\u093E \u0906\u092A \u0935\u093E\u0938\u094D\u0924\u0935 \u092E\u0947\u0902 \u0905\u092A\u0928\u093E \u0916\u093E\u0924\u093E \u0939\u091F\u093E\u0928\u093E \u091A\u093E\u0939\u0924\u0947 \u0939\u0948\u0902? \u0916\u093E\u0924\u0947 \u0915\u094B \u092A\u0941\u0928\u0930\u094D\u0938\u094D\u0925\u093E\u092A\u093F\u0924 \u0928\u0939\u0940\u0902 \u0915\u093F\u092F\u093E \u091C\u093E \u0938\u0915\u0924\u093E \u0939\u0948 \u0914\u0930 \u0908\u092E\u0947\u0932 \u092A\u0924\u093E \u092B\u093F\u0930 \u0938\u0947 \u092A\u0902\u091C\u0940\u0915\u0943\u0924 \u0928\u0939\u0940\u0902 \u0915\u093F\u092F\u093E \u091C\u093E \u0938\u0915\u0924\u093E \u0939\u0948\u0964",
        "deleteAccountReasonInfo_msg": "\u0935\u0948\u0915\u0932\u094D\u092A\u093F\u0915: \u0939\u092E \u0907\u0938\u0915\u0940 \u0938\u0930\u093E\u0939\u0928\u093E \u0915\u0930\u0924\u0947 \u0939\u0948\u0902 \u092F\u0926\u093F \u0906\u092A\u0928\u0947 \u0939\u092E\u0947\u0902 \u090F\u0915 \u0915\u093E\u0930\u0923 \u0926\u093F\u092F\u093E \u0939\u0948 \u0915\u093F \u0906\u092A \u0916\u093E\u0924\u0947 \u0915\u094B \u0915\u094D\u092F\u094B\u0902 \u0939\u091F\u093E\u0928\u093E \u091A\u093E\u0939\u0924\u0947 \u0939\u0948\u0902 \u0924\u093E\u0915\u093F \u0939\u092E \u0906\u0917\u0947 \u091F\u0941\u091F\u093E\u0928\u094B\u091F\u093E  \u0938\u0941\u0927\u093E\u0930 \u0938\u0915\u0947\u0902.",
        "deleteAccountReason_label": "\u0915\u094D\u092F\u0942\u0902 ?",
        "deleteAccountWithTakeoverConfirm_msg": "\u0915\u094D\u092F\u093E \u0906\u092A \u0935\u093E\u0938\u094D\u0924\u0935 \u092E\u0947\u0902 \u0905\u092A\u0928\u093E \u0916\u093E\u0924\u093E \u092C\u0902\u0926 \u0915\u0930\u0928\u093E \u091A\u093E\u0939\u0924\u0947 \u0939\u0948\u0902? \u0906\u092A\u0915\u0947 \u0908\u092E\u0947\u0932 \u092A\u0924\u0947 \u0916\u093E\u0924\u0947 \u0915\u094B \u0907\u0938 \u0916\u093E\u0924\u0947 {1} \u0926\u094D\u0935\u093E\u0930\u093E \u0932\u093F\u092F\u093E \u091C\u093E \u0938\u0915\u0924\u093E \u0939\u0948\u0964 ",
        "deleteAlias_msg": "\u0908\u092E\u0947\u0932 \u0909\u092A\u0928\u093E\u092E '{1}' \u0905\u092C \u0939\u091F\u093E \u0926\u093F\u092F\u093E \u091C\u093E\u090F\u0917\u093E. \u0906\u092A \u0908\u092E\u0947\u0932 \u090F\u0932\u093E\u0907\u091C \u0915\u0947 \u0930\u0942\u092A \u092E\u0947\u0902 \u092A\u0924\u0947 \u0915\u093E \u0909\u092A\u092F\u094B\u0917 \u092B\u093F\u0930 \u0938\u0947 \u0915\u0930 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902 \u092F\u093E \u0928\u090F \u0909\u092A\u092F\u094B\u0917\u0915\u0930\u094D\u0924\u093E \u0915\u0947 \u0932\u093F\u090F \u0909\u092A\u092F\u094B\u0917 \u0915\u0930 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902.",
