        "invalidVatIdNumber_msg": "\uB0A9\uC138\uC790 \uC2DD\uBCC4 \uBC88\uD638 (VAT-ID) \uAC12\uC774 \uC720\uD6A8\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
        "invalidVatIdValidationFailed_msg": "\uB0A9\uC138\uC790 \uC2DD\uBCC4 \uBC88\uD638 \uAC12 \uAC80\uC99D\uC5D0 \uC2E4\uD328\uD588\uC2B5\uB2C8\uB2E4. \uB2E4\uC2DC \uC2DC\uB3C4\uD574\uC8FC\uC138\uC694.",
        "invitationMailBody_msg": "\uC548\uB155\uD558\uC138\uC694!<br><br>\uC774\uAC74 \uC800\uC758 \uC0C8 \uC774\uBA54\uC77C \uC8FC\uC18C\uC785\uB2C8\uB2E4. Tutanota\uB294 \uD504\uB77C\uC774\uBC84\uC2DC \uAD8C\uB9AC\uB97C \uBCF4\uD638\uD558\uAE30 \uC704\uD574 \uC644\uC804\uD788 \uC554\uD638\uD654\uB41C, \uAD11\uACE0 \uC5C6\uB294 \uBA54\uC77C\uD568\uC744 \uC81C\uACF5\uD569\uB2C8\uB2E4. \uC790\uB3D9 \uC554\uD638\uD654\uB97C \uD1B5\uD574 \uBD09\uC778 \uD3B8\uC9C0\uB97C \uBCF4\uB0B4\uB294 \uAC83\uB9CC\uD07C \uC548\uC804\uD558\uAC8C \uC774\uBA54\uC77C\uC744 \uACF5\uC720\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uB9C8\uC9C0\uB9C9\uC73C\uB85C \uC6B0\uB9AC\uC758 \uB370\uC774\uD130\uB294 \uC624\uC9C1 \uC6B0\uB9AC\uC5D0\uAC8C\uB9CC \uC18D\uD558\uBA70 \uB2E4\uB978 \uB204\uAD6C\uB3C4 \uC811\uADFC\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.<br><br>\uC9C0\uAE08 Tutanota\uC640 \uD568\uAED8 \uD558\uC138\uC694: <br>{registrationLink}<br><br><br>{username} \uB4DC\uB9BC<br><br>\uCD94\uC2E0: Tutanota\uB294 \uBB34\uB8CC\uC774\uBA70 1 GB \uBB34\uB8CC \uC800\uC7A5\uC18C\uB97C \uD3EC\uD568\uD569\uB2C8\uB2E4. \uB610\uD55C, \uC624\uD508\uC18C\uC2A4\uC785\uB2C8\uB2E4: {githubLink}",
        "invitationMailSubject_msg": "\uC800\uC758 \uC0C8\uB85C\uC6B4 \uC774\uBA54\uC77C \uC8FC\uC18C\uC785\uB2C8\uB2E4 - Tutanota\uC640 \uD568\uAED8 \uD504\uB77C\uC774\uBC84\uC2DC\uB97C \uB2E4\uC2DC \uC5BB\uC73C\uC138\uC694!",
        "invitation_label": "\uCD08\uB300",
        "invitedToEvent_msg": "\uBCF8 \uC774\uBCA4\uD2B8\uC5D0 \uCC38\uC5EC\uD558\uB3C4\uB85D \uCD08\uB300\uBC1B\uC558\uC2B5\uB2C8\uB2E4. \uCC38\uC11D\uD558\uC2DC\uACA0\uC2B5\uB2C8\uAE4C?",
        "invited_label": "\uCD08\uB300\uB428",
        "invite_alt": "\uCD08\uB300",
        "invoiceAddressInfoBusiness_msg": "\uB2F9\uC2E0\uC758 \uC774\uB984/\uD68C\uC0AC\uC640 \uCCAD\uAD6C\uC11C \uC8FC\uC18C\uB97C \uB123\uC5B4\uC8FC\uC138\uC694 (\uCD5C\uB300 5\uC904).",
        "invoiceAddressInfoPrivate_msg": "\uC774 \uC815\uBCF4\uB294 \uAC1C\uC778 \uACE0\uAC1D\uC5D0\uAC8C\uB294 \uD544\uC218\uAC00 \uC544\uB2D9\uB2C8\uB2E4 (\uCD5C\uB300 5\uC904).",
        "invoiceAddress_label": "\uC778\uBCF4\uC774\uC2A4 \uC774\uB984\uACFC \uC8FC\uC18C",
        "invoiceCountryInfoBusiness_msg": "\uAC70\uC8FC\uD558\uACE0 \uACC4\uC2DC\uB294 \uAD6D\uAC00\uB97C \uC120\uD0DD\uD574 \uC8FC\uC138\uC694",
        "invoiceCountryInfoConsumer_msg": "\uC774\uAC83\uC740 \uBD80\uAC00\uAC00\uCE58\uC138\uB97C \uACC4\uC0B0\uD558\uB294\uB370 \uD544\uC694\uD569\uB2C8\uB2E4.",
        "invoiceCountry_label": "\uAD6D\uAC00",
        "invoiceData_msg": "\uCCAD\uAD6C \uB370\uC774\uD130",
        "invoiceMailBodyAutomatic_msg": "\uC0C8 \uCCAD\uAD6C\uC11C {1}\uC740 \uD655\uC778 \uAC00\uB2A5\uD569\uB2C8\uB2E4. {2}\uC5D0\uC11C \uB2E4\uC6B4\uBC1B\uC73C\uC2E4 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uCD1D\uC561\uC740 \uC790\uB3D9\uC73C\uB85C \uCD9C\uAE08\uB429\uB2C8\uB2E4.",
        "invoiceMailBodyOnAccount_msg": "\uBC88\uD638 {1}\uC758 \uC0C8 \uC778\uBCF4\uC774\uC2A4\uAC00 \uC788\uC2B5\uB2C8\uB2E4. {2}\uC5D0\uC11C \uB2E4\uC6B4\uB85C\uB4DC\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uACB0\uC81C\uB294 \uC778\uBCF4\uC774\uC2A4 \uB0A0\uC9DC\uB85C\uBD80\uD130 7\uC77C \uB3D9\uC548 \uAC00\uB2A5\uD569\uB2C8\uB2E4.",
        "invoiceMailSubject_msg": "\uC0C8 Tutanota \uCCAD\uAD6C\uC11C",
        "invoiceNotPaidUser_msg": "\uC8C4\uC1A1\uD569\uB2C8\uB2E4, \uD604\uC7AC \uC774\uBA54\uC77C\uC744 \uBCF4\uB0BC \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.",
        "invoiceNotPaid_msg": "\uC8C4\uC1A1\uD569\uB2C8\uB2E4. \uD604\uC7AC \uD55C \uAC1C \uC774\uC0C1\uC758 \uCCAD\uAD6C\uC11C\uAC00 \uACB0\uC81C\uAC00 \uB418\uC9C0 \uC54A\uC544 \uC774\uBA54\uC77C\uC744 \uBCF4\uB0B4\uC2E4 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. '\uC124\uC815' \u21E8 '\uACB0\uC81C \uC815\uBCF4'\uC5D0\uC11C \uACB0\uC81C \uC815\uBCF4\uB97C \uC5C5\uB370\uC774\uD2B8 \uD558\uACE0 \uACB0\uC81C\uD574\uC8FC\uC138\uC694.",
        "invoicePayConfirm_msg": "\uC774\uC81C \uB2E4\uC74C \uAE08\uC561\uC744 \uCD9C\uAE08\uD560 \uC608\uC815\uC785\uB2C8\uB2E4:",
