        "addCustomDomainAddresses_title": "\u0D94\u0DB6\u0D9C\u0DDA \u0D85\u0DB7\u0DD2\u0DBB\u0DD4\u0DA0\u0DD2 \u0DC0\u0DC3\u0DB8 \u0DC3\u0DB3\u0DC4\u0DCF \u0DC0\u0DD2-\u0DAD\u0DD0\u0DB4\u0DD0\u0DBD\u0DCA \u0DBD\u0DD2\u0DB4\u0DD2\u0DB1 \u0D91\u0D9A\u0DAD\u0DD4 \u0D9A\u0DBB\u0DB1\u0DCA\u0DB1",
        "addCustomDomainAdresses_msg": "\u0DC0\u0DC3\u0DB8 \u0D94\u0DB6\u0D9C\u0DDA \u0D9C\u0DD2\u0DAB\u0DD4\u0DB8\u0DA7 \u0DB4\u0DC0\u0DBB\u0DCF \u0D87\u0DAD. \u0D94\u0DB6\u0D9C\u0DDA \u0D85\u0DB7\u0DD2\u0DBB\u0DD4\u0DA0\u0DD2 \u0DC0\u0DC3\u0DB8 \u0DB7\u0DCF\u0DC0\u0DD2\u0DAD\u0DCF \u0D9A\u0DD2\u0DBB\u0DD3\u0DB8\u0DA7 \u0D85\u0DC0\u0DB8 \u0DC0\u0DC1\u0DBA\u0DD9\u0DB1\u0DCA \u0DC0\u0DAD\u0DCA\u0DB8\u0DB1\u0DCA \u0DB4\u0DBB\u0DD2\u0DC1\u0DD3\u0DBD\u0D9A\u0DA7 \u0D91\u0D9A\u0DCA \u0DC0\u0DD2-\u0DAD\u0DD0\u0DB4\u0DD0\u0DBD\u0DCA \u0D85\u0DB4\u0DB1\u0DCF\u0DB8\u0DBA\u0D9A\u0DCA \u0D91\u0D9A\u0DAD\u0DD4 \u0D9A\u0DBB\u0DB1\u0DCA\u0DB1. \u0DC0\u0DD9\u0DB1\u0DD4\u0DC0\u0DA7, \u0DB1\u0DC0 \u0DB4\u0DBB\u0DD2\u0DC1\u0DD3\u0DBD\u0D9A\u0DBA\u0DD2\u0DB1\u0DCA \u0D85\u0DB7\u0DD2\u0DBB\u0DD4\u0DA0\u0DD2 \u0DC0\u0DC3\u0DB8\u0D9A \u0DC0\u0DD2-\u0DAD\u0DD0\u0DB4\u0DD0\u0DBD\u0DCA \u0DBD\u0DD2\u0DB4\u0DD2\u0DB1\u0DBA\u0D9A\u0DCA \u0DC3\u0DB8\u0D9F \u0DAF \u0D91\u0D9A\u0DAD\u0DD4 \u0D9A\u0DC5 \u0DC4\u0DD0\u0D9A\u0DD2\u0DBA.",
        "addCustomDomainAliases_msg": "\u0D94\u0DB6\u0DA7 \u0DAD\u0DC0\u0DAD\u0DCA \u0DC0\u0DD2-\u0DAD\u0DD0\u0DB4\u0DD1\u0DBD\u0D9A\u0DCA \u0D87\u0DC0\u0DD0\u0DC3\u0DD2 \u0DB1\u0DB8\u0DCA \u0DC0\u0DAD\u0DCA\u0DB8\u0DB1\u0DCA \u0DAD\u0DD0.\u0DB4\u0DD9. \u0DA7 \u0DC0\u0DD2-\u0DAD\u0DD0\u0DB4\u0DD0\u0DBD\u0DCA \u0D85\u0DB4\u0DB1\u0DCF\u0DB8\u0DBA\u0D9A\u0DCA \u0D91\u0D9A\u0DCA\u0D9A\u0DBB\u0DB1\u0DCA\u0DB1",
        "addCustomDomainUsers_msg": "\u0D94\u0DB6\u0DA7 \u0DC0\u0DD9\u0DB1\u0DAD\u0DCA \u0DB8\u0DD2\u0DB1\u0DD2\u0DC3\u0DD4\u0DB1\u0DCA \u0DC3\u0DB3\u0DC4\u0DCF \u0DC0\u0DD2-\u0DAD\u0DD0\u0DB4\u0DD0\u0DBD\u0DCA \u0DBD\u0DD2\u0DB4\u0DD2\u0DB1 \u0D87\u0DC0\u0DD0\u0DC3\u0DD2 \u0DB1\u0DB8\u0DCA \u0DB1\u0DC0 \u0DB4\u0DBB\u0DD2\u0DC1\u0DD3\u0DBD\u0D9A\u0DBA\u0DD2\u0DB1\u0DCA \u0DC4\u0DDD \u0DB4\u0DC0\u0DAD\u0DCA\u0DB1\u0DCF \u0DB4\u0DBB\u0DD2\u0DC1\u0DD3\u0DBD\u0D9A\u0DBA\u0DD2\u0DB1\u0DCA \u0DC3\u0DB3\u0DC4\u0DCF \u0DB1\u0DC0 \u0DC0\u0DD2-\u0DAD\u0DD0\u0DB4\u0DD0\u0DBD\u0DCA \u0D85\u0DB4\u0DB1\u0DCF\u0DB8 \u0D91\u0D9A\u0DCA\u0D9A\u0DBB\u0DB1\u0DCA\u0DB1 .",
        "addCustomDomain_action": "\u0D85\u0DB7\u0DD2\u0DBB\u0DD4\u0DA0\u0DD2 \u0DC0\u0DC3\u0DB8 \u0D91\u0D9A\u0DAD\u0DD4 \u0D9A\u0DBB\u0DB1\u0DCA\u0DB1",
        "addDNSValue_label": "\u0D85\u0D9C\u0DBA \u0D91\u0D9A\u0DCA\u0D9A\u0DBB\u0DB1\u0DCA\u0DB1",
        "addEmailAlias_label": "\u0DC0\u0DD2-\u0DAD\u0DD0\u0DB4\u0DD0\u0DBD\u0DCA \u0D85\u0DB4\u0DB1\u0DCF\u0DB8\u0DBA\u0D9A\u0DCA \u0D91\u0D9A\u0DAD\u0DD4 \u0D9A\u0DBB\u0DB1\u0DCA\u0DB1",
        "addEntry_label": "\u0DB1\u0DD2\u0DC0\u0DDA\u0DC1\u0DD2\u0DAD\u0DBA\u0D9A\u0DCA \u0DBA\u0DDC\u0DAF\u0DB1\u0DCA\u0DB1",
        "addEnumValue_action": "\u0D85\u0DB1\u0DD4\u0D9C\u0DAB\u0D9A \u0D85\u0D9C\u0DBA \u0DBA\u0DDC\u0DAF\u0DB1\u0DCA\u0DB1",
        "addGroup_label": "\u0DC3\u0DB8\u0DD6\u0DC4\u0DBA \u0D91\u0D9A\u0DAD\u0DD4 \u0D9A\u0DBB\u0DB1\u0DCA\u0DB1",
        "addGuest_label": "\u0D85\u0DB8\u0DD4\u0DAD\u0DCA\u0DAD\u0DD9\u0D9A\u0DD4 \u0D91\u0D9A\u0DCA\u0D9A\u0DBB\u0DB1\u0DCA\u0DB1",
        "addInboxRule_action": "\u0D91\u0DB1\u0DBD\u0DD2\u0DB4\u0DD2 \u0DB1\u0DD3\u0DAD\u0DD2\u0DBA \u0D91\u0D9A\u0DCA\u0D9A\u0DBB\u0DB1\u0DCA\u0DB1",
        "addLanguage_action": "\u0DB7\u0DCF\u0DC2\u0DCF\u0DC0\u0D9A\u0DCA \u0D91\u0D9A\u0DCA\u0D9A\u0DBB\u0DB1\u0DCA\u0DB1",
        "addNext_action": "\u0DAD\u0DDA\u0DBB\u0DD3\u0DB8\u0DA7 \u0D8A\u0DC5\u0D9F \u0D85\u0DAE\u0D9A\u0DBA \u0D91\u0D9A\u0DCA\u0D9A\u0DBB\u0DB1\u0DCA\u0DB1",
        "addOpenOTPApp_action": "\u0DC3\u0DAD\u0DCA\u200D\u0DBA\u0DCF\u0DB4\u0DB1 \u0DBA\u0DD9\u0DAF\u0DD4\u0DB8\u0DA7 \u0DBA\u0DDC\u0DAF\u0DB1\u0DCA\u0DB1",
        "addParticipant_action": "\u0DC3\u0DC4\u0DB7\u0DCF\u0D9C\u0DD3\u0DC0\u0DB1\u0DCA\u0DB1\u0DCF \u0D91\u0D9A\u0DCA\u0D9A\u0DBB\u0DB1\u0DCA\u0DB1",
        "addPrevious_action": "\u0DAD\u0DDA\u0DBB\u0DD3\u0DB8\u0DA7 \u0DB4\u0DD9\u0DBB \u0D85\u0DAE\u0D9A\u0DBA \u0D91\u0D9A\u0DCA\u0D9A\u0DBB\u0DB1\u0DCA\u0DB1",
        "addResponsiblePerson_label": "\u0DC0\u0D9C\u0D9A\u0DD2\u0DC0\u0DBA\u0DD4\u0DAD\u0DD4 \u0DB4\u0DD4\u0DAF\u0DCA\u0D9C\u0DBD\u0DBA\u0DD9\u0D9A\u0DD4 \u0D91\u0D9A\u0DCA\u0D9A\u0DBB\u0DB1\u0DCA\u0DB1",
        "addressesAlreadyInUse_msg": "\u0DB4\u0DC4\u0DAD \u0DC0\u0DD2-\u0DAD\u0DD0\u0DB4\u0DD1\u0DBD \u0DAF\u0DD0\u0DB1\u0DA7\u0DB8\u0DAD\u0DCA \u0DB7\u0DCF\u0DC0\u0DD2\u0DAD\u0DBA\u0DDA \u0DB4\u0DC0\u0DAD\u0DD3:",
