        "addTemplate_label": "\u0DB1\u0DC0 \u0D85\u0DA0\u0DCA\u0DA0\u0DD4\u0DC0",
        "addToDict_action": '\u0DC1\u0DB6\u0DCA\u0DAF\u0D9A\u0DDD\u0DC2\u0DBA\u0DA7"{word}" \u0D91\u0D9A\u0DCA\u0D9A\u0DBB\u0DB1\u0DCA\u0DB1',
        "addUsers_action": "\u0DB4\u0DBB\u0DD2\u0DC1\u0DD3\u0DBD\u0D9A \u0D91\u0D9A\u0DCA \u0D9A\u0DBB\u0DB1\u0DCA\u0DB1",
        "addUsers_title": "\u0DB4\u0DBB\u0DD2\u0DC1\u0DD3\u0DBD\u0D9A\u0DBA\u0DD2\u0DB1\u0DCA \u0D91\u0D9A\u0DCA\u0D9A\u0DBB\u0DB1\u0DC0\u0DCF\u0DAF?",
        "addUserToGroup_label": "\u0DC3\u0DCF\u0DB8\u0DCF\u0DA2\u0DD2\u0D9A\u0DBA\u0DCF \u0D91\u0D9A\u0DCA\u0D9A\u0DBB\u0DB1\u0DCA\u0DB1",
        "add_action": "\u0D91\u0D9A\u0DAD\u0DD4",
        "adminCustomDomain_label": "\u0D85\u0DB7\u0DD2\u0DBB\u0DD4\u0DA0\u0DD2 \u0DC0\u0DC3\u0DB8",
        "adminDeleteAccount_action": "\u0D9C\u0DD2\u0DAB\u0DD4\u0DB8 \u0DB8\u0D9A\u0DB1\u0DCA\u0DB1",
        "adminEmailSettings_action": "\u0DC0\u0DD2-\u0DAD\u0DD0\u0DB4\u0DD1\u0DBD",
        "administratedBy_label": "\u0DC0\u0DD2\u0DC3\u0DD2\u0DB1\u0DCA \u0DB4\u0DBB\u0DD2\u0DB4\u0DCF\u0DBD\u0DB1\u0DBA \u0D9A\u0DD9\u0DBB\u0DDA",
        "administratedGroups_label": "\u0DB4\u0DBB\u0DD2\u0DB4\u0DCF\u0DBD\u0DB1\u0DBA \u0DC0\u0DB1 \u0DC3\u0DB8\u0DD6\u0DC4",
        "administrator_label": "\u0DB4\u0DBB\u0DD2\u0DB4\u0DCF\u0DBD\u0D9A",
        "adminMaxNbrOfAliasesReached_msg": "\u0D8B\u0DB4\u0DBB\u0DD2\u0DB8 \u0D85\u0DB4\u0DB1\u0DCF\u0DB8 \u0D9C\u0DAB\u0DB1\u0DA7 \u0DBD\u0D9F\u0DCF \u0DC0\u0DD3 \u0D87\u0DAD.",
        "adminPayment_action": "\u0D9C\u0DD9\u0DC0\u0DD3\u0DB8",
