        "adminSettings_label": "\u0DB4\u0DBB\u0DD2\u0DB4\u0DCF\u0DBD\u0D9A \u0DC3\u0DD0\u0D9A\u0DC3\u0DD4\u0DB8\u0DCA",
        "adminSpamRuleInfo_msg": "\u0D85\u0DBA\u0DCF\u0DA0\u0DD2\u0DAD \u0DB1\u0DD3\u0DAD\u0DD2 \u0DC0\u0DD2\u0DB1\u0DCA\u200D\u0DBA\u0DCF\u0DC3 \u0D9A\u0DD2\u0DBB\u0DD3\u0DB8\u0DA7 \u0DC0\u0DD2\u0DC3\u0DCA\u0DAD\u0DBB: ",
        "adminSpam_action": "\u0D85\u0DBA\u0DCF\u0DA0\u0DD2\u0DAD \u0DB1\u0DD3\u0DAD\u0DD2",
        "adminSubscription_action": "\u0DAF\u0DCF\u0DBA\u0D9A\u0DAD\u0DCA\u0DC0\u0DBA",
        "adminUserList_action": "\u0DB4\u0DBB\u0DD2\u0DC1\u0DD3\u0DBD\u0D9A \u0D9A\u0DC5\u0DB8\u0DAB\u0DCF\u0D9A\u0DBB\u0DB1\u0DBA",
        "advanced_label": "\u0DC0\u0DD0\u0DA9\u0DD2\u0DAF\u0DD4\u0DBB",
        "ageConfirmation_msg": "\u0DB8\u0DA7 \u0D85\u0DC0\u0DB8 \u0DC0\u0DC1\u0DBA\u0DD9\u0DB1\u0DCA \u0D85\u0DC0\u0DD4. 16 \u0D9A\u0DCA \u0DC0\u0DAD\u0DCA \u0DC0\u0DDA.",
        "agenda_label": "\u0DC0\u0DD0\u0DA9 \u0DC3\u0DA7\u0DC4\u0DB1",
        "allDay_label": "\u0DAF\u0DC0\u0DC3 \u0DB4\u0DD4\u0DBB\u0DCF\u0DB8",
        "allowExternalContentSender_action": "\u0DC3\u0DD0\u0DB8\u0DC0\u0DD2\u0DA7\u0DB8 \u0DBA\u0DC0\u0DB1\u0DCA\u0DB1\u0DCF \u0DC0\u0DD2\u0DC1\u0DCA\u0DC0\u0DCF\u0DC3 \u0D9A\u0DBB\u0DB1\u0DCA\u0DB1",
        "allowOperation_msg": "\u0DB8\u0DD9\u0DBA\u0DA7 \u0D89\u0DA9 \u0DAF\u0DD3\u0DB8\u0DA7 \u0D87\u0DC0\u0DD0\u0DC3\u0DD2\u0DAF?",
        "allowPushNotification_msg": "\u0DB1\u0DC0 \u0DC0\u0DD2-\u0DAD\u0DD0\u0DB4\u0DD0\u0DBD\u0DCA \u0DC3\u0DB3\u0DC4\u0DCF \u0DAD\u0DBD\u0DCA\u0DBD\u0DD4 \u0DAF\u0DD0\u0DB1\u0DD4\u0DB8\u0DCA\u0DAF\u0DD3\u0DB8\u0DCA \u0DC3\u0DCA\u0DAE\u0DCF\u0DC0\u0DBB\u0DC0 \u0DBD\u0DD0\u0DB6\u0DD3\u0DB8\u0DA7, \u0DA7\u0DD4\u0DA7\u0DCF\u0DB1\u0DDD\u0DA7\u0DCF \u0DC3\u0DB3\u0DC4\u0DCF \u0DB6\u0DD0\u0DA7\u0DBB\u0DD2 \u0DB4\u0DCA\u200D\u0DBB\u0DC1\u0DC3\u0DCA\u0DAD\u0DD2\u0D9A\u0DBB\u0DAB\u0DBA \u0D85\u0D9A\u0DCA\u200D\u0DBB\u0DD2\u0DBA \u0D9A\u0DD2\u0DBB\u0DD3\u0DB8\u0DA7 \u0D91\u0D9A\u0D9F \u0DC0\u0DB1\u0DCA\u0DB1. \u0D94\u0DB6\u0DA7 \u0DB8\u0DD9\u0DBA \u0DB4\u0DC3\u0DD4\u0DC0 \u0DB4\u0DAF\u0DCA\u0DB0\u0DAD\u0DD2 \u0DC3\u0DD0\u0D9A\u0DC3\u0DD4\u0DB8\u0DCA \u0DAD\u0DD4\u0DC5 \u0DC0\u0DD9\u0DB1\u0DC3\u0DCA \u0D9A\u0DC5 \u0DC4\u0DD0\u0D9A\u0DD2\u0DBA.",
        "all_contacts_label": "\u0DC3\u0DD2\u0DBA\u0DC5\u0DD4\u0DB8 \u0DC3\u0DB6\u0DB3\u0DAD\u0DCF",
        "all_label": "\u0DC3\u0DD2\u0DBA\u0DBD\u0DCA\u0DBD",
        "alreadyMember_msg": "\u0D94\u0DB6 \u0DAF\u0DD0\u0DB1\u0DA7\u0DB8\u0DAD\u0DCA \u0DB8\u0DD9\u0DB8 \u0DAF\u0DD2\u0DB1 \u0DAF\u0DC3\u0DD4\u0DB1\u0DD9\u0DC4\u0DD2 \u0DC3\u0DC4\u0DB7\u0DCF\u0D9C\u0DD3\u0DC0\u0DB1\u0DCA\u0DB1\u0DD9\u0D9A\u0DD2. \u0D94\u0DB6 \u0DB1\u0DC0 \u0D87\u0DBB\u0DBA\u0DD4\u0DB8 \u0DB4\u0DD2\u0DC5\u0DD2\u0D9C\u0DD0\u0DB1\u0DD3\u0DB8\u0DA7 \u0D87\u0DC0\u0DD0\u0DC3\u0DD2 \u0DB1\u0DB8\u0DCA \u0DB4\u0DC5\u0DB8\u0DD4\u0DC0 \u0D94\u0DB6\u0D9C\u0DDA \u0DC3\u0DC4\u0DB7\u0DCF\u0D9C\u0DD3\u0DAD\u0DCA\u0DC0\u0DBA \u0D89\u0DC0\u0DAD\u0DCA \u0D9A\u0DC5 \u0DBA\u0DD4\u0DAD\u0DD4\u0DBA.",
        "alreadyReplied_msg": "\u0D94\u0DB6 \u0DB8\u0DD9\u0DB8 \u0D87\u0DBB\u0DBA\u0DD4\u0DB8\u0DA7 \u0DB4\u0DD2\u0DC5\u0DD2\u0DAD\u0DD4\u0DBB\u0DD4 \u0DAF\u0DD4\u0DB1\u0DCA\u0DB1\u0DCF.",
        "alreadyTemplateGroupMember_msg": "\u0D94\u0DB6 \u0DAF\u0DD0\u0DB1\u0DA7\u0DB8\u0DAD\u0DCA \u0DB8\u0DD9\u0DB8 \u0D85\u0DA0\u0DCA\u0DA0\u0DD4 \u0DC3\u0DB8\u0DD6\u0DC4\u0DBA \u0DB7\u0DCF\u0DC0\u0DD2\u0DAD\u0DCF \u0D9A\u0DBB\u0DBA\u0DD2. \u0DB8\u0DD9\u0DB8 \u0D86\u0DBB\u0DCF\u0DB0\u0DB1\u0DBA \u0DB4\u0DD2\u0DC5\u0DD2\u0D9C\u0DD0\u0DB1\u0DD3\u0DB8\u0DA7 \u0DB4\u0DD9\u0DBB \u0D94\u0DB6\u0DA7 \u0DC3\u0DB8\u0DD6\u0DC4\u0DBA\u0DD9\u0DB1\u0DCA \u0D89\u0DC0\u0DAD\u0DCA \u0DC0\u0DD3\u0DB8\u0DA7 \u0DC3\u0DD2\u0DAF\u0DD4 \u0DC0\u0DB1\u0DD4 \u0D87\u0DAD.",
        "alwaysAsk_action": "\u0DC3\u0DD0\u0DB8\u0DC0\u0DD2\u0DA7\u0DB8 \u0D85\u0DC3\u0DB1\u0DCA\u0DB1",
        "alwaysReport_action": "\u0DC3\u0DD0\u0DB8\u0DC0\u0DD2\u0DA7\u0DB8 \u0DC0\u0DCF\u0DBB\u0DCA\u0DAD\u0DCF \u0D9A\u0DBB\u0DB1\u0DCA\u0DB1",
        "amountUsedOf_label": "{amount} / {totalAmount}",
