        "businessChangeInfo_msg": "\u0DC0\u0DCA\u200D\u0DBA\u0DCF\u0DB4\u0DCF\u0DBB\u0DD2\u0D9A \u0DB7\u0DCF\u0DC0\u0DD2\u0DAD\u0DBA\u0DA7 \u0D9C\u0DD2\u0DAB\u0DD4\u0DB8 \u0DB8\u0DCF\u0DBB\u0DD4\u0D9A\u0DD2\u0DBB\u0DD3\u0DB8\u0DA7 \u0DC0\u0DCF\u0DBB\u0DCA\u0DAB\u0DCF\u0DC0\u0DDA \u0DAF\u0DAD\u0DCA\u0DAD \u0DAD\u0DC4\u0DC0\u0DD4\u0DBB\u0DD4 \u0D9A\u0DBB\u0DB1\u0DCA\u0DB1.",
        "businessCustomerAutoBusinessFeature_msg": "\u0DC0\u0DCA\u200D\u0DBA\u0DCF\u0DB4\u0DCF\u0DBB\u0DD2\u0D9A \u0DB4\u0DCF\u0DBB\u0DD2\u0DB7\u0DDD\u0D9C\u0DD2\u0D9A\u0DBA\u0DD2\u0DB1\u0DCA \u0DC3\u0DB3\u0DC4\u0DCF \u0DC0\u0DB1 \u0DC3\u0DD2\u0DBA\u0DC5\u0DD4\u0DB8 \u0DAF\u0DCF\u0DBA\u0D9A\u0DAD\u0DCA\u0DC0 \u0DC3\u0DB8\u0D9F \u0DC0\u0DCA\u200D\u0DBA\u0DCF\u0DB4\u0DCF\u0DBB\u0DD2\u0D9A \u0DC0\u0DD2\u0DC1\u0DDA\u0DC2\u0DCF\u0D82\u0D9C\u0DBA \u0DC3\u0DCA\u0DC0\u0DBA\u0D82\u0D9A\u0DCA\u200D\u0DBB\u0DD3\u0DBA\u0DC0 \u0DC0\u0DD9\u0DB1\u0DCA \u0D9A\u0DD9\u0DBB\u0DD9\u0DB1 \u0DB6\u0DC0 \u0DC3\u0DBD\u0D9A\u0DB1\u0DCA\u0DB1.",
        "businessCustomerNeedsBusinessFeaturePlan_msg": "\u0D94\u0DB6\u0D9C\u0DDA \u0DC0\u0DAD\u0DCA\u0DB8\u0DB1\u0DCA \u0DAF\u0DCF\u0DBA\u0D9A\u0DAD\u0DCA\u0DC0 \u0DC3\u0DD0\u0DBD\u0DC3\u0DD4\u0DB8 \u0DC0\u0DCA\u200D\u0DBA\u0DCF\u0DB4\u0DCF\u0DBB\u0DD2\u0D9A \u0DC0\u0DD2\u0DC1\u0DDA\u0DC2\u0DCF\u0D82\u0D9C\u0DBA\u0DD9\u0DB1\u0DCA \u0DAD\u0DDC\u0DBB\u0DC0 {plan} ({price}) \u0DC0\u0DDA.",
        "businessDeletionWarning_msg": "\u0DC3\u0DD2\u0DBA\u0DC5\u0DD4\u0DB8 \u0DB4\u0DBB\u0DD2\u0DC1\u0DD3\u0DBD\u0D9A\u0DBA\u0DD2\u0DB1\u0DCA \u0DC3\u0DB3\u0DC4\u0DCF \u0DC0\u0DCA\u200D\u0DBA\u0DCF\u0DB4\u0DCF\u0DBB\u0DD2\u0D9A \u0DC0\u0DD2\u0DC1\u0DDA\u0DC2\u0DCF\u0D82\u0D9C\u0DBA \u0DAF\u0DD0\u0DB1\u0DCA \u0D9A\u0DCA\u200D\u0DBB\u0DD2\u0DBA\u0DCF\u0DC0\u0DD2\u0DBB\u0DC4\u0DD2\u0DAD \u0DC0\u0DB1\u0DD4 \u0D87\u0DAD. \u0DC3\u0DCA\u0DC0\u0DBA\u0D82\u0DB4\u0DCA\u200D\u0DBB\u0DAD\u0DD2\u0DA0\u0DCF\u0DBB\u0D9A \u0DC3\u0DC4 \u0DAF\u0DD2\u0DB1 \u0DAF\u0DC3\u0DD4\u0DB1\u0DCA \u0D87\u0DBB\u0DBA\u0DD4\u0DB8\u0DCA \u0D85\u0DB6\u0DBD \u0DC0\u0DB1\u0DD4 \u0D87\u0DAD. \u0D91\u0D9A\u0DCA \u0D85\u0DB7\u0DD2\u0DBB\u0DD4\u0DA0\u0DD2 \u0DC0\u0DD2-\u0DAD\u0DD0\u0DB4\u0DD0\u0DBD\u0DCA \u0DC0\u0DC3\u0DB8\u0D9A\u0DA7 \u0DB4\u0DB8\u0DAB\u0D9A\u0DCA \u0D89\u0DA9 \u0D87\u0DAD.",
        "businessFeatureRequiredGeneral_msg": "\u0DB8\u0DD9\u0DB8 \u0D9A\u0DD8\u0DAD\u0DCA\u200D\u0DBA \u0DC3\u0DD2\u0DAF\u0DD4\u0D9A\u0DBB \u0D9C\u0DD0\u0DB1\u0DD3\u0DB8\u0DA7 \u0DC0\u0DCA\u200D\u0DBA\u0DCF\u0DB4\u0DCF\u0DBB\u0DD2\u0D9A \u0DC0\u0DD2\u0DC1\u0DDA\u0DC2\u0DCF\u0D82\u0D9C\u0DBA \u0D87\u0DAB\u0DC0\u0DD4\u0DB8\u0DCA \u0D9A\u0DD2\u0DBB\u0DD3\u0DB8\u0DA7 \u0DC3\u0DD2\u0DAF\u0DD4\u0DC0\u0DDA.",
        "businessFeatureRequiredInvite_msg": "\u0DC3\u0DD2\u0DAF\u0DD4\u0DC0\u0DD3\u0DB8\u0DCA \u0D87\u0DBB\u0DBA\u0DD4\u0DB8\u0DCA \u0DBA\u0DD0\u0DC0\u0DD3\u0DB8\u0DA7 \u0D94\u0DB6 \u0DC0\u0DCA\u200D\u0DBA\u0DCF\u0DB4\u0DCF\u0DBB\u0DD2\u0D9A \u0DC0\u0DD2\u0DC1\u0DDA\u0DC2\u0DCF\u0D82\u0D9C\u0DBA \u0D87\u0DAB\u0DC0\u0DD4\u0DB8\u0DCA \u0D9A\u0DC5 \u0DBA\u0DD4\u0DAD\u0DD4\u0DBA.",
        "businessFeatureRequiredMultipleDomains_msg": "\u0D85\u0DB7\u0DD2\u0DBB\u0DD4\u0DA0\u0DD2 \u0DC0\u0DD2-\u0DAD\u0DD0\u0DB4\u0DD0\u0DBD\u0DCA \u0DC0\u0DC3\u0DB8\u0DCA \u0D9A\u0DD2\u0DC4\u0DD2\u0DB4\u0DBA\u0D9A\u0DCA \u0D91\u0D9A\u0DCA \u0D9A\u0DD2\u0DBB\u0DD3\u0DB8\u0DA7 \u0D94\u0DB6 \u0DC0\u0DCA\u200D\u0DBA\u0DCF\u0DB4\u0DCF\u0DBB\u0DD2\u0D9A \u0DC0\u0DD2\u0DC1\u0DDA\u0DC2\u0DCF\u0D82\u0D9C\u0DBA \u0D87\u0DAB\u0DC0\u0DD4\u0DB8\u0DCA \u0D9A\u0DC5 \u0DBA\u0DD4\u0DAD\u0DD4\u0DBA.",
        "businessFeatureRequiredTemplates_msg": "\u0D85\u0DA0\u0DCA\u0DA0\u0DD4 \u0DB7\u0DCF\u0DC0\u0DD2\u0DAD\u0DBA\u0DA7 \u0DC0\u0DCA\u200D\u0DBA\u0DCF\u0DB4\u0DCF\u0DBB\u0DD2\u0D9A \u0DC0\u0DD2\u0DC1\u0DDA\u0DC2\u0DCF\u0D82\u0D9C\u0DBA \u0D87\u0DC0\u0DD0\u0DC3\u0DD2\u0DBA.",
        "businessFeature_label": "\u0DC0\u0DCA\u200D\u0DBA\u0DCF\u0DB4\u0DCF\u0DBB\u0DD2\u0D9A \u0DC0\u0DD2\u0DC1\u0DDA\u0DC2\u0DCF\u0D82\u0D9C\u0DBA",
        "businessIncluded_msg": "\u0DC0\u0DCA\u200D\u0DBA\u0DCF\u0DB4\u0DCF\u0DBB\u0DD2\u0D9A \u0DC0\u0DD2\u0DC1\u0DDA\u0DC2\u0DCF\u0D82\u0D9C\u0DBA \u0D87\u0DAD\u0DD4\u0DC5\u0DAD\u0DCA\u0DBA.",
        "businessOrPrivateUsage_label": "\u0DB7\u0DCF\u0DC0\u0DD2\u0DAD\u0DBA",
        "businessUseUpgradeNeeded_msg": "\u0D9A\u0DAB\u0D9C\u0DCF\u0DA7\u0DD4\u0DBA\u0DD2, \u0D94\u0DB6\u0DA7 \u0DB8\u0DDA \u0DB8\u0DDC\u0DC4\u0DDC\u0DAD\u0DD9\u0DCA \u0DC0\u0DD2-\u0DAD\u0DD0\u0DB4\u0DD0\u0DBD\u0DCA \u0DBA\u0DD0\u0DC0\u0DD3\u0DB8\u0DA7 \u0DC4\u0DDD \u0DBD\u0DD0\u0DB6\u0DD3\u0DB8\u0DA7 \u0D89\u0DA9 \u0DB1\u0DDC\u0DAF\u0DDA (\u0DA7\u0DD4\u0DA7\u0DCF\u0DB1\u0DDD\u0DA7\u0DCF \u0D85\u0DBD\u0DD9\u0DC0\u0DD2 \u0DC3\u0DC4\u0DCF\u0DBA\u0DA7 \u0DC4\u0DD0\u0DBB sales@tutao.de) \u0DB8\u0DB1\u0DCA\u0DAF, \u0D94\u0DB6\u0DA7 \u0DC0\u0DCA\u200D\u0DBA\u0DCF\u0DB4\u0DCF\u0DBB\u0DD2\u0D9A \u0D9C\u0DD2\u0DAB\u0DD4\u0DB8\u0D9A\u0DCA \u0D87\u0DAD\u0DD2 \u0DB6\u0DD0\u0DC0\u0DD2\u0DB1\u0DCA \u0D91\u0DBA \u0D9C\u0DD9\u0DC0\u0DB1 \u0DAF\u0DCF\u0DBA\u0D9A\u0DAD\u0DCA\u0DC0\u0DBA\u0D9A\u0DCA \u0DC3\u0DB8\u0D9F \u0DB4\u0DB8\u0DAB\u0D9A\u0DCA \u0DB7\u0DCF\u0DC0\u0DD2\u0DAD\u0DCF \u0D9A\u0DC5 \u0DC4\u0DD0\u0D9A\u0DD2\u0DBA. \u0DAF\u0DD0\u0DB1\u0DCA \u0D9C\u0DD9\u0DC0\u0DB1 \u0DAF\u0DCF\u0DBA\u0D9A\u0DAD\u0DCA\u0DC0\u0DBA\u0D9A\u0DA7 \u0D8B\u0DAD\u0DCA\u0DC1\u0DCA\u200D\u0DBB\u0DDA\u0DAB\u0DD2 \u0D9A\u0DBB\u0DB1\u0DCA\u0DB1.",
        "buyEmailAliasInfo_msg": "\u0DAD\u0DD2\u0DB6\u0DD9\u0DB1 \u0DC0\u0DD2-\u0DAD\u0DD0\u0DB4\u0DD0\u0DBD\u0DCA \u0D85\u0DB4\u0DB1\u0DCF\u0DB8 \u0D9C\u0DAB\u0DB1 \u0DC0\u0DD9\u0DB1\u0DC3\u0DCA \u0D9A\u0DD2\u0DBB\u0DD3\u0DB8\u0DA7 \u0DC0\u0DD2-\u0DAD\u0DD0\u0DB4\u0DD0\u0DBD\u0DCA \u0D85\u0DB4\u0DB1\u0DCF\u0DB8 \u0D87\u0DC3\u0DD4\u0DBB\u0DD4\u0DB8\u0DCA  \u0DC0\u0DBD\u0DD2\u0DB1\u0DCA \u0D91\u0D9A\u0D9A\u0DCA \u0DAD\u0DDD\u0DBB\u0DB1\u0DCA\u0DB1. \u0DC0\u0DD9\u0DB1\u0DCA \u0D9A\u0DC5 \u0DC0\u0DD2-\u0DAD\u0DD0\u0DB4\u0DD0\u0DBD\u0DCA \u0D85\u0DB4\u0DB1\u0DCF\u0DB8 \u0D95\u0DB1\u0DD1\u0DB8 \u0D85\u0DBA\u0DD9\u0D9A\u0DD4\u0DA7 \u0DB7\u0DCF\u0DC0\u0DD2\u0DAD\u0DCF \u0D9A\u0DC5 \u0DC4\u0DD0\u0D9A\u0DD2\u0DBA.",
