        "copyLink_action": "\u0DC3\u0DB6\u0DD0\u0DB3\u0DD2\u0DBA\u0DDA \u0DBD\u0DD2\u0DB4\u0DD2\u0DB1\u0DBA \u0DB4\u0DD2\u0DA7\u0DB4\u0DAD\u0DCA",
        "copyToClipboard_action": "\u0DB4\u0DC3\u0DD4\u0DBB\u0DD4\u0DB4\u0DD4\u0DC0\u0DBB\u0DD4\u0DC0\u0DA7 \u0DB4\u0DD2\u0DA7\u0DB4\u0DAD\u0DCA \u0D9A\u0DBB\u0DB1\u0DCA\u0DB1",
        "copy_action": "\u0DB4\u0DD2\u0DA7\u0DB4\u0DAD\u0DCA",
        "correctDNSValue_label": "\u0DC4\u0DBB\u0DD2",
        "correctValues_msg": "\u0DC0\u0DBD\u0D82\u0D9C\u0DD4 \u0DB1\u0DDC\u0DC0\u0DB1 \u0D86\u0D9A\u0DD8\u0DAD\u0DD2\u0DBA\u0D9A\u0DCA \u0DC3\u0DB8\u0D9F \u0D87\u0DAD\u0DD2 \u0D85\u0D9C\u0DBA\u0DB1\u0DCA \u0DB1\u0DD2\u0DC0\u0DBB\u0DAF\u0DD2 \u0D9A\u0DBB\u0DB1\u0DCA\u0DB1.",
        "corruptedValue_msg": "\u0D85\u0D9C\u0DBA \u0DAF\u0DBB\u0DCA\u0DC1\u0DB1\u0DBA \u0D9A\u0DC5 \u0DB1\u0DDC\u0DC4\u0DD0\u0D9A\u0DD2\u0DBA.",
        "corrupted_msg": "\u0DB8\u0DD9\u0DB8 \u0D85\u0D82\u0D9C\u0DBA \u0DB1\u0DD2\u0DC0\u0DBB\u0DAF\u0DD2\u0DC0 \u0DAF\u0DBB\u0DCA\u0DC1\u0DB1\u0DBA \u0D9A\u0DD2\u0DBB\u0DD3\u0DB8\u0DA7 \u0DB1\u0DDC\u0DC4\u0DD0\u0D9A\u0DD2\u0DBA.\n\n\u0DC4\u0DD0\u0D9A\u0DD2\u0DB1\u0DB8\u0DCA, \u0DB4\u0DAB\u0DD2\u0DC0\u0DD2\u0DA9\u0DBA \u0DBA\u0DC5\u0DD2 \u0D91\u0DC0\u0DB1 \u0DBD\u0DD9\u0DC3 \u0D91\u0DC0\u0DB1\u0DCA\u0DB1\u0DCF\u0DA7 \u0DB4\u0DC0\u0DC3\u0DB1\u0DCA\u0DB1.",
        "couldNotAttachFile_msg": "\u0D9C\u0DDC\u0DB1\u0DD4\u0DC0 \u0DB4\u0DD6\u0DBB\u0DAB\u0DBA \u0DC0\u0DD3\u0DB8\u0DA7 \u0DB1\u0DDC\u0DC4\u0DD0\u0D9A\u0DD2 \u0DC0\u0DD2\u0DBA.",
        "couldNotAuthU2f_msg": "\u0D86\u0DBB\u0D9A\u0DCA\u200D\u0DC2\u0DAB \u0DBA\u0DAD\u0DD4\u0DBB \u0DC3\u0DB8\u0D9F\u0DD2\u0DB1\u0DCA \u0DC3\u0DAD\u0DCA\u200D\u0DBA\u0DCF\u0DB4\u0DB1\u0DBA \u0D9A\u0DC5 \u0DB1\u0DDC\u0DC4\u0DD0\u0D9A\u0DD2\u0DBA.",
        "couldNotUnlockCredentials_msg": "\u0D85\u0D9A\u0DCA\u0DAD\u0DB4\u0DAD\u0DCA\u200D\u0DBB \u0D85\u0D9C\u0DD4\u0DC5\u0DD4 \u0DC4\u0DD0\u0DBB\u0DD3\u0DB8\u0DA7 \u0DB1\u0DDC\u0DC4\u0DD0\u0D9A\u0DD2\u0DBA\u0DD2: {reason}",
        "createAccountAccessDeactivated_msg": "\u0D85\u0DB1\u0DD2\u0DC3\u0DD2 \u0D9A\u0DCA\u200D\u0DBB\u0DD2\u0DBA\u0DCF \u0DC0\u0DD0\u0DC5\u0DD0\u0D9A\u0DCA\u0DC0\u0DD3\u0DB8\u0DA7 \u0DBD\u0DD2\u0DBA\u0DCF\u0DB4\u0DAF\u0DD2\u0D82\u0DA0\u0DD2\u0DBA \u0DAD\u0DCF\u0DC0\u0D9A\u0DCF\u0DBD\u0DD2\u0D9A\u0DC0 \u0D94\u0DB6\u0D9C\u0DDA \u0D85.\u0DA2\u0DCF.\u0D9A\u0DD9. \u0DBD\u0DD2\u0DB4\u0DD2\u0DB1\u0DBA\u0DA7  \u0D85\u0DC0\u0DC4\u0DD2\u0DBB \u0D9A\u0DBB \u0D87\u0DAD. \u0DB4\u0DC3\u0DD4\u0DC0 \u0DB1\u0DD0\u0DC0\u0DAD \u0D8B\u0DAD\u0DCA\u0DC3\u0DCF\u0DC4 \u0D9A\u0DBB\u0DB1\u0DCA\u0DB1 \u0DC4\u0DDD \u0DC0\u0DD9\u0DB1\u0DAD\u0DCA \u0D85\u0DB1\u0DCA\u0DAD\u0DBB\u0DCA\u0DA2\u0DCF\u0DBD \u0DC3\u0DB8\u0DCA\u0DB6\u0DB1\u0DCA\u0DB0\u0DAD\u0DCF\u0DC0\u0DBA\u0D9A\u0DCA \u0DB7\u0DCF\u0DC0\u0DD2\u0DAD\u0DCF \u0D9A\u0DBB\u0DB1\u0DCA\u0DB1.",
        "createAccountInvalidCaptcha_msg": "\u0D9A\u0DAB\u0D9C\u0DCF\u0DA7\u0DD4\u0DBA\u0DD2, \u0D8B\u0DAD\u0DCA\u0DAD\u0DBB\u0DBA \u0DC0\u0DD0\u0DBB\u0DAF\u0DD2\u0DBA. \u0DB1\u0DD0\u0DC0\u0DAD \u0D8B\u0DAD\u0DCA\u0DC3\u0DCF\u0DC4 \u0D9A\u0DBB\u0DB1\u0DCA\u0DB1.",
