        "createActionStatus_msg": "\u0DB4\u0DBB\u0DD2\u0DC1\u0DD3\u0DBD\u0D9A\u0DBA\u0DD2\u0DB1\u0DCA \u0DC3\u0DD1\u0DAF\u0DD9\u0DB8\u0DD2\u0DB1\u0DCA. \u0D9C\u0DD2\u0DAB\u0DD4\u0DB8\u0DCA {index} / {count} \u0D85\u0DC4\u0DC0\u0DBB\u0DBA\u0DD2\u202F...",
        "createContactForm_label": "\u0DC3\u0DB6\u0DB3\u0DAD\u0DCF \u0D86\u0D9A\u0DD8\u0DAD\u0DD2\u0DB4\u0DAD\u0DCA\u200D\u0DBB\u0DBA\u0D9A\u0DCA \u0DC3\u0DCF\u0DAF\u0DB1\u0DCA\u0DB1",
        "createContactRequest_action": "\u0DB4\u0DAB\u0DD2\u0DC0\u0DD2\u0DA9\u0DBA \u0DBD\u0DD2\u0DBA\u0DB1\u0DCA\u0DB1",
        "createContactsForRecipients_action": "\u0DC0\u0DD2-\u0DAD\u0DD0\u0DB4\u0DD1\u0DBD \u0DBA\u0DC0\u0DB1 \u0DC0\u0DD2\u0DA7 \u0DC3\u0DD2\u0DBA\u0DC5\u0DD4\u0DB8 \u0DBD\u0DB6\u0DB1\u0DCA\u0DB1\u0DB1\u0DCA \u0DC3\u0DB3\u0DC4\u0DCF \u0DC3\u0DB6\u0DB3\u0DAD\u0DCF \u0DC3\u0DCF\u0DAF\u0DB1\u0DCA\u0DB1",
