        "searchGroups_placeholder": "\u0DC3\u0DB8\u0DD6\u0DC4 \u0DC3\u0DB3\u0DC4\u0DCF \u0DC3\u0DDC\u0DBA\u0DB1\u0DCA\u0DB1",
