        "secondFactorConfirmLoginNoIp_msg": '\u0D94\u0DB6 "{clientIdentifier}" \u0D85\u0DB1\u0DD4\u0D9C\u0DCA\u200D\u0DBB\u0DCF\u0DC4\u0D9A\u0DBA\u0DD9\u0DB1\u0DCA \u0D87\u0DAD\u0DD4\u0DC5\u0DD4\u0DC0\u0DD3\u0DB8\u0DA7 \u0D89\u0DA9 \u0DAF\u0DD3\u0DB8\u0DA7 \u0D9A\u0DD0\u0DB8\u0DAD\u0DD2\u0DAF?',
        "secondFactorConfirmLogin_label": "\u0DB4\u0DD2\u0DC0\u0DD2\u0DC3\u0DD4\u0DB8 \u0DAD\u0DC4\u0DC0\u0DD4\u0DBB\u0DD4\u0DC0",
        "secondFactorConfirmLogin_msg": '\u0D85.\u0DA2\u0DCF.\u0D9A\u0DD9. {ipAddress} \u0DC3\u0DB8\u0D9F "{clientIdentifier}" \u0D85\u0DB1\u0DD4\u0D9C\u0DCA\u200D\u0DBB\u0DCF\u0DC4\u0D9A\u0DBA \u0DC0\u0DD9\u0DAD\u0DD2\u0DB1\u0DCA \u0DB4\u0DD2\u0DC0\u0DD2\u0DC3\u0DD3\u0DB8\u0DA7 \u0D89\u0DA9 \u0DAF\u0DD3\u0DB8\u0DA7 \u0D94\u0DB6 \u0D9A\u0DD0\u0DB8\u0DAD\u0DD2\u0DAF??',
        "secondFactorNameInfo_msg": "\u0DC0\u0DDB\u0D9A\u0DBD\u0DCA\u0DB4\u0DD2\u0DAD\u0DBA\u0DD2: \u0DC4\u0DD0\u0DB3\u0DD4\u0DB1\u0DD4\u0DB8\u0DDA \u0DB1\u0DB8.",
        "secondFactorPendingOtherClientOnly_msg": "\u0D85\u0DB1\u0DD9\u0D9A\u0DCA \u0D85\u0DB1\u0DD4\u0D9C\u0DCA\u200D\u0DBB\u0DCF\u0DC4\u0D9A\u0DBA\u0D9A\u0DCA \u0DC0\u0DD9\u0DAD\u0DD2\u0DB1\u0DCA \u0DB8\u0DD9\u0DB8 \u0DB4\u0DD2\u0DC0\u0DD2\u0DC3\u0DD4\u0DB8 \u0DB4\u0DD2\u0DC5\u0DD2\u0D9C\u0DB1\u0DCA\u0DB1.",
        "secondFactorPending_msg": "\u0D94\u0DB6\u0D9C\u0DDA \u0DAF\u0DCA\u0DC0\u0DD2 \u0DC3\u0DCF\u0DB0\u0D9A\u0DBA \u0DB8\u0D9C\u0DD2\u0DB1\u0DCA \u0DC3\u0DAD\u0DCA\u200D\u0DBA\u0DCF\u0DB4\u0DB1\u0DBA \u0D9A\u0DBB\u0DB1\u0DCA\u0DB1 \u0DC4\u0DDD \u0DC0\u0DD9\u0DB1\u0DAD\u0DCA \u0D85\u0DB1\u0DD4\u0D9C\u0DCA\u200D\u0DBB\u0DCF\u0DC4\u0D9A\u0DBA\u0D9A\u0DD2\u0DB1\u0DCA \u0DB8\u0DD9\u0DB8 \u0DB4\u0DD2\u0DC0\u0DD2\u0DC3\u0DD4\u0DB8 \u0DB4\u0DD2\u0DC5\u0DD2\u0D9C\u0DB1\u0DCA\u0DB1.",
        "secondMergeContact_label": "\u0DC3\u0DB6\u0DB3\u0DAD\u0DCF\u0DC0\u0DBA 2",
        "secondReminderAutomatic_msg": "\u0D9A\u0DAB\u0D9C\u0DCF\u0DA7\u0DD4\u0DBA\u0DD2, \u0D94\u0DB6\u0D9C\u0DDA \u0DA7\u0DD4\u0DA7\u0DCF\u0DB1\u0DDD\u0DA7\u0DCF \u0D9C\u0DD2\u0DAB\u0DD4\u0DB8 \u0DC3\u0DB3\u0DC4\u0DCF \u0D85\u0DB4\u0DA7 \u0DAD\u0DC0\u0DB8\u0DAD\u0DCA \u0D9C\u0DD9\u0DC0\u0DD3\u0DB8 \u0DBD\u0DD0\u0DB6\u0DD3 \u0DB1\u0DD0\u0DAD. \u0D91\u0DB6\u0DD0\u0DC0\u0DD2\u0DB1\u0DCA, \u0D94\u0DB6\u0D9C\u0DDA \u0D9C\u0DD9\u0DC0\u0DD3\u0DB8\u0DDA \u0DC0\u0DD2\u0DC3\u0DCA\u0DAD\u0DBB '\u0DC3\u0DD0\u0D9A\u0DC3\u0DD4\u0DB8\u0DCA' -> '\u0D9C\u0DD9\u0DC0\u0DD3\u0DB8' \u0DAD\u0DD4\u0DC5 \u0DAD\u0DC4\u0DC0\u0DD4\u0DBB\u0DD4 \u0D9A\u0DBB\u0DB1 \u0DBD\u0DD9\u0DC3 \u0D85\u0DB4\u0DD2 \u0D94\u0DB6\u0D9C\u0DD9\u0DB1\u0DCA \u0D9A\u0DCF\u0DBB\u0DD4\u0DAB\u0DD2\u0D9A\u0DC0 \u0D89\u0DBD\u0DCA\u0DBD\u0DCF \u0DC3\u0DD2\u0DA7\u0DD2\u0DB8\u0DD4. \u0DC0\u0DD0\u0DA9\u0DD2\u0DAF\u0DD4\u0DBB \u0DC0\u0DD2\u0DC3\u0DCA\u0DAD\u0DBB \u0DC3\u0DB3\u0DC4\u0DCF \u0D91\u0DB8 \u0DB4\u0DD2\u0DA7\u0DD4\u0DC0\u0DDA \u0D94\u0DB6\u0D9C\u0DDA \u0DC0\u0DCF\u0DBB\u0DCA\u0DAB\u0DCF\u0DC0 \u0DB4\u0DBB\u0DD3\u0D9A\u0DCA\u200D\u0DC2\u0DCF \u0D9A\u0DC5 \u0DC4\u0DD0\u0D9A\u0DD2\u0DBA. \u0DC3\u0DAD\u0DD2 \u0DAF\u0DD9\u0D9A\u0D9A\u0DCA \u0D87\u0DAD\u0DD4\u0DC5\u0DAD \u0D85\u0DB4\u0DA7 \u0D9C\u0DD9\u0DC0\u0DD3\u0DB8 \u0DB1\u0DDC\u0DBD\u0DD0\u0DB6\u0DD4\u0DAB\u0DC4\u0DDC\u0DAD\u0DCA \u0D94\u0DB6\u0D9C\u0DDA \u0D9C\u0DD2\u0DAB\u0DD4\u0DB8 \u0D85\u0D9A\u0DCA\u200D\u0DBB\u0DD2\u0DBA \u0D9A\u0DD2\u0DBB\u0DD3\u0DB8\u0DA7 \u0DC3\u0DD2\u0DAF\u0DD4\u0DC0\u0DDA.",
