        "showMoreUpgrade_action": "\u0DAF\u0DCF\u0DBA\u0D9A\u0DAD\u0DCA\u0DC0 \u0DC0\u0DD2\u0D9A\u0DBD\u0DCA\u0DB4",
        "showMore_action": "\u0DAD\u0DC0 \u0DB4\u0DD9\u0DB1\u0DCA\u0DC0\u0DB1\u0DCA\u0DB1",
        "showRejectReason_action": "\u0DB1\u0DD2\u0DC2\u0DCA\u0DB4\u0DCA\u200D\u0DBB\u0DB7 \u0DC0\u0DD3\u0DB8\u0DA7 \u0DC4\u0DDA\u0DAD\u0DD4\u0DC0 \u0DB4\u0DD9\u0DB1\u0DCA\u0DC0\u0DB1\u0DCA\u0DB1",
        "showRichTextToolbar_action": "\u0D86\u0D9A\u0DD8\u0DAD\u0DD2\u0D9A\u0DBB\u0DB1 \u0DB8\u0DD9\u0DC0\u0DBD\u0DB8\u0DCA \u0DB4\u0DD9\u0DB1\u0DCA\u0DC0\u0DB1\u0DCA\u0DB1",
        "showURL_alt": "\u0DC3\u0DB6\u0DD0\u0DB3\u0DD2\u0DBA \u0DC0\u0DD2\u0DC0\u0DD8\u0DAD \u0D9A\u0DBB\u0DB1\u0DCA\u0DB1",
