        "unregistered_label": "\u0DBD\u0DD2\u0DBA\u0DCF\u0DB4\u0DAF\u0DD2\u0D82\u0DA0\u0DD2 \u0DB1\u0DD0\u0DAD",
        "unsubscribeConfirm_msg": "\u0D94\u0DB6\u0D9C\u0DDA \u0DAF\u0DCF\u0DBA\u0D9A\u0DAD\u0DCA\u0DC0\u0DBA \u0DB1\u0DD0\u0DC0\u0DD0\u0DAD\u0DCA\u0DC0\u0DD3\u0DB8\u0DA7 \u0D85\u0DC0\u0DC1\u0DCA\u200D\u0DBA\u0DAF? \u0D94\u0DB6\u0D9C\u0DDA \u0D9C\u0DD2\u0DAB\u0DD4\u0DB8 \u0DAF\u0DD0\u0DB1\u0DCA \u0DB1\u0DDC\u0DB8\u0DD2\u0DBD\u0DDA \u0DBD\u0DD9\u0DC3 \u0DC3\u0DD0\u0D9A\u0DC3\u0DD9\u0DB1 \u0D85\u0DAD\u0DBB \u0D94\u0DB6\u0D9C\u0DDA \u0D9C\u0DD9\u0DC0\u0DB1 \u0DC0\u0DD2\u0DC1\u0DDA\u0DC2\u0DCF\u0D82\u0D9C \u0D85\u0DC4\u0DD2\u0DB8\u0DD2 \u0DC0\u0DB1\u0DD4 \u0D87\u0DAD. \u0DAD\u0DC0\u0DAF \u0DB1\u0DDC\u0DB8\u0DD2\u0DBD\u0DDA \u0D9C\u0DD2\u0DAB\u0DD4\u0DB8\u0DCA \u0DB8\u0DCF\u0DC3 \u0DC4\u0DBA\u0D9A\u0DA7 \u0DC0\u0DA9\u0DCF \u0DB7\u0DCF\u0DC0\u0DD2\u0DAD\u0DCF \u0DB1\u0DDC\u0D9A\u0DC5\u0DC4\u0DDC\u0DAD\u0DCA \u0DB8\u0D9A\u0DCF \u0DAF\u0DB8\u0DB1 \u0DB6\u0DC0 \u0D9A\u0DBB\u0DD4\u0DAB\u0DCF\u0DC0\u0DD9\u0DB1\u0DCA \u0DC3\u0DBD\u0D9A\u0DB1\u0DCA\u0DB1.",
        "unsubscribeFailed_msg": "\u0DAD\u0DD0\u0DB4\u0DD0\u0DBD\u0DCA \u0DBD\u0DDA\u0D9B\u0DB1\u0DBA \u0DC4\u0DDD \u0DB4\u0DD4\u0DC0\u0DAD\u0DCA\u0DB4\u0DAD\u0DCA\u200D\u0DBB\u0DD2\u0D9A\u0DCF \u0D85\u0DC0\u0DBD\u0D82\u0D9C\u0DD4 \u0D9A\u0DD2\u0DBB\u0DD3\u0DB8\u0DA7 \u0DB1\u0DDC\u0DC4\u0DD0\u0D9A\u0DD2 \u0DC0\u0DD2\u0DBA.",
        "unsubscribeSuccessful_msg": "\u0DAD\u0DD0\u0DB4\u0DD0\u0DBD\u0DCA \u0DBD\u0DDA\u0D9B\u0DB1\u0DBA \u0DC4\u0DDD \u0DB4\u0DD4\u0DC0\u0DAD\u0DCA\u0DB4\u0DAD\u0DCA\u200D\u0DBB\u0DD2\u0D9A\u0DCF \u0DC3\u0DCF\u0DBB\u0DCA\u0DAE\u0D9A\u0DC0 \u0D85\u0DC0\u0DBD\u0D82\u0D9C\u0DD4 \u0D9A\u0DD9\u0DBB\u0DD2\u0DAB\u0DD2.",
        "unsubscribe_action": "\u0DAF\u0DCF\u0DBA\u0D9A\u0DAD\u0DCA\u0DC0\u0DBA \u0D85\u0DC4\u0DDD\u0DC3\u0DD2\u0DBA",
        "unsuccessfulDrop_msg": "\u0DAF\u0DAD\u0DCA\u0DAD \u0DB6\u0DCF\u0D9C\u0DD0\u0DB1\u0DD3\u0DB8 \u0DB1\u0DD2\u0DB8 \u0DC0\u0DD3 \u0DB1\u0DD0\u0DAD\u0DD2 \u0DB1\u0DD2\u0DC3\u0DCF \u0D87\u0DAF \u0DAF\u0DD0\u0DB8\u0DD3\u0DB8 \u0DC3\u0DCF\u0DBB\u0DCA\u0DAE\u0D9A \u0DB1\u0DDC\u0DC0\u0DD2\u0DAB\u0DD2. \u0DB4\u0DCA\u200D\u0DBB\u0D9C\u0DAD\u0DD2 \u0DAD\u0DD3\u0DBB\u0DD4\u0DC0 \u0DB4\u0DD2\u0DBB\u0DD4\u0DAB\u0DD4 \u0DB4\u0DC3\u0DD4 \u0D94\u0DB6\u0DA7 \u0DBA\u0DC5\u0DD2 \u0D8B\u0DAD\u0DCA\u0DC3\u0DCF\u0DC4 \u0D9A\u0DC5 \u0DC4\u0DD0\u0D9A\u0DD2\u0DBA.",
        "unsupportedBrowserOverlay_msg": "\u0D94\u0DB6 \u0DC3\u0DC4\u0DCF\u0DBA \u0DB1\u0DDC\u0DAF\u0D9A\u0DCA\u0DC0\u0DB1 \u0D85\u0DAD\u0DD2\u0DBB\u0DD2\u0D9A\u0DCA\u0DC3\u0DD4\u0DC0\u0D9A\u0DCA \u0DB7\u0DCF\u0DC0\u0DD2\u0DAD\u0DCF \u0D9A\u0DBB\u0DBA\u0DD2. \u0DC3\u0DB8\u0DC4\u0DBB \u0D9A\u0DCA\u200D\u0DBB\u0DD2\u0DBA\u0DCF\u0D9A\u0DCF\u0DBB\u0DD3\u0DAD\u0DCA\u0DC0 \u0DC3\u0DD3\u0DB8\u0DCF \u0DC0\u0DD2\u0DBA \u0DC4\u0DD0\u0D9A\u0DD2\u0DBA.",
        "unsupportedBrowser_msg": "\u0D85\u0DB4\u0DDC\u0DBA\u0DD2! \u0D85\u0DB4\u0DA7 \u0DC3\u0DB8\u0DCF\u0DC0\u0DB1\u0DCA\u0DB1. \u0D85\u0DC0\u0DCF\u0DC3\u0DB1\u0DCF\u0DC0\u0D9A\u0DA7, \u0D94\u0DB6\u0D9C\u0DDA \u0D85\u0DAD\u0DD2\u0DBB\u0DD2\u0D9A\u0DCA\u0DC3\u0DD4\u0DC0\u0DA7 \u0DC3\u0DC4\u0DCF\u0DBA \u0DB1\u0DDC\u0DAF\u0D9A\u0DCA\u0DC0\u0DBA\u0DD2 \u0DC4\u0DDD \u0DBA\u0DBD\u0DCA \u0DB4\u0DD0\u0DB1 \u0D9C\u0DDC\u0DC3\u0DCA \u0D87\u0DAD. \u0DB4\u0DC4\u0DAD \u0D85\u0DAD\u0DD2\u0DBB\u0DD2\u0D9A\u0DCA\u0DC3\u0DD4\u0DC0\u0D9A \u0DB1\u0DC0\u0DAD\u0DB8 \u0D85\u0DB1\u0DD4\u0DC0\u0DCF\u0DAF\u0DBA\u0D9A\u0DCA \u0DB7\u0DCF\u0DC0\u0DD2\u0DAD\u0DCF \u0D9A\u0DBB\u0DB1\u0DCA\u0DB1:",
        "until_label": "\u0DAD\u0DD9\u0D9A\u0DCA",
        "updateAdminshipGlobalAdmin_msg": "\u0D9C\u0DDD\u0DBD\u0DD3\u0DBA \u0DB4\u0DBB\u0DD2\u0DB4\u0DCF\u0DBD\u0D9A\u0DBA\u0DD9\u0D9A\u0DD4\u0D9C\u0DDA \u0DB4\u0DBB\u0DD2\u0DB4\u0DCF\u0DBD\u0D9A\u0DAD\u0DCA\u0DC0\u0DBA \u0D94\u0DB6\u0DA7 \u0DC0\u0DD9\u0DB1\u0DC3\u0DCA \u0D9A\u0DC5 \u0DB1\u0DDC\u0DC4\u0DD0\u0D9A\u0DD2\u0DBA.",
        "updateAdminshipLocalAdminGroupError_msg": "\u0DC3\u0DCA\u0DAE\u0DCF\u0DB1\u0DD3\u0DBA \u0DB4\u0DBB\u0DD2\u0DB4\u0DCF\u0DBD\u0DB1 \u0DC3\u0DB8\u0DD6\u0DC4\u0DBA\u0D9A \u0DB4\u0DBB\u0DD2\u0DB4\u0DCF\u0DBD\u0D9A\u0DAD\u0DCA\u0DC0\u0DBA \u0D94\u0DB6\u0DA7 \u0DC0\u0DD9\u0DB1\u0DC3\u0DCA \u0D9A\u0DC5 \u0DB1\u0DDC\u0DC4\u0DD0\u0D9A\u0DD2\u0DBA.",
        "updateAvailable_label": "\u0DA7\u0DD4\u0DA7\u0DCF\u0DB1\u0DDD\u0DA7\u0DCF \u0DC0\u0DD0\u0DA9\u0DAD\u0DBD\u0DBA\u0DA7 \u0DBA\u0DCF\u0DC0\u0DAD\u0DCA\u0D9A\u0DCF\u0DBD\u0DBA\u0D9A\u0DCA \u0DAD\u0DD2\u0DB6\u0DDA ({version})",
        "updateFound_label": "\u0DB1\u0DC0 \u0D85\u0DB1\u0DD4\u0DC0\u0DCF\u0DAF\u0DBA\u0D9A\u0DCA \u0DAD\u0DD2\u0DB6\u0DDA.",
        "updateOwnAdminship_msg": "\u0D94\u0DB6\u0D9C\u0DD9\u0DCA\u0DB8 \u0DB4\u0DBB\u0DD2\u0DC1\u0DD3\u0DBD\u0D9A\u0DBA\u0DCF\u0D9C\u0DDA \u0DB4\u0DBB\u0DD2\u0DB4\u0DCF\u0DBD\u0D9A\u0DAD\u0DCA\u0DC0\u0DBA \u0DC0\u0DD9\u0DB1\u0DC3\u0DCA \u0D9A\u0DC5 \u0DB1\u0DDC\u0DC4\u0DD0\u0D9A\u0DD2\u0DBA.",
        "updatePaymentDataBusy_msg": "\u0D9C\u0DD9\u0DC0\u0DD3\u0DB8\u0DDA \u0DAF\u0DAD\u0DCA\u0DAD \u0DAD\u0DC4\u0DC0\u0DD4\u0DBB\u0DD4 \u0D9A\u0DD9\u0DBB\u0DD9\u0DB8\u0DD2\u0DB1\u0DCA. \u0DBB\u0DD0\u0DB3\u0DD9\u0DB1\u0DCA\u0DB1, \u0DB8\u0DD9\u0DBA\u0DA7 \u0DC0\u0DD2\u0DB1\u0DCF\u0DA9\u0DD2\u0DBA\u0D9A\u0DCA \u0D9C\u0DAD\u0DC0\u0DD2\u0DBA \u0DC4\u0DD0\u0D9A\u0DD2\u0DBA.",
        "update_action": "\u0DBA\u0DCF\u0DC0\u0DAD\u0DCA\u0D9A\u0DCF\u0DBD",
        "upgradeConfirm_msg": "\u0D87\u0DAB\u0DC0\u0DD4\u0DB8 \u0DAD\u0DC4\u0DC0\u0DD4\u0DBB\u0DD4 \u0D9A\u0DBB\u0DB1\u0DCA\u0DB1!",
        "upgradeNeeded_msg": "\u0D9A\u0DAB\u0D9C\u0DCF\u0DA7\u0DD4\u0DBA\u0DD2, \u0D94\u0DB6\u0DA7 \u0DC0\u0DD2-\u0DAD\u0DD0\u0DB4\u0DD0\u0DBD\u0DCA \u0DBA\u0DD0\u0DC0\u0DD3\u0DB8\u0DA7 \u0DC4\u0DDD \u0DBD\u0DD0\u0DB6\u0DD3\u0DB8\u0DA7 \u0D89\u0DA9 \u0DB1\u0DDC\u0DAF\u0DDA (\u0DA7\u0DD4\u0DA7\u0DCF\u0DB1\u0DDD\u0DA7\u0DCF \u0D85\u0DBD\u0DD9\u0DC0\u0DD2 \u0DC3\u0DC4\u0DCF\u0DBA\u0DA7 \u0DC4\u0DD0\u0DBB sales@tutao.de) \u0DB8\u0DB1\u0DCA\u0DAF, \u0D94\u0DB6 \u0D9C\u0DD9\u0DC0\u0DB1 \u0DAF\u0DCF\u0DBA\u0D9A\u0DAD\u0DCA\u0DC0\u0DBA \u0D87\u0DAB\u0DC0\u0DD4\u0DB8\u0DCA \u0D9A\u0DD2\u0DBB\u0DD3\u0DB8 \u0D85\u0DC0\u0DC3\u0DB1\u0DCA \u0D9A\u0DC5 \u0DBA\u0DD4\u0DAD\u0DD4\u0DBA.",
        "upgradePlan_msg": "\u0D94\u0DB6\u0D9C\u0DDA \u0DAF\u0DCF\u0DBA\u0D9A\u0DAD\u0DCA\u0DC0\u0DBA {plan} \u0DC0\u0DD9\u0DAD \u0D8B\u0DAD\u0DCA\u0DC1\u0DCA\u200D\u0DBB\u0DDA\u0DAB\u0DD2 \u0D9A\u0DD9\u0DBB\u0DDA.",
        "upgradePremium_label": "\u0D86\u0DB0\u0DD2\u0D9A\u0DCA\u200D\u0DBA\u0DBA",
        "upgradeProNoReduction_msg": "\u0DB4\u0DD9\u0DBB \u0D87\u0DAB\u0DC0\u0DD4\u0DB8\u0DCA \u0D9A\u0DC5 \u0DC0\u0DD2\u0DC1\u0DCF\u0DBD \u0D86\u0DA0\u0DBA\u0DB1\u0DBA \u0DC4\u0DDD \u0D85\u0DB4\u0DB1\u0DCF\u0DB8 \u0D87\u0DC3\u0DD4\u0DBB\u0DD4\u0DB8\u0DCA \u0D85\u0DA9\u0DD4 \u0DB1\u0DDC\u0D9A\u0DD9\u0DBB\u0DD9\u0DB1\u0DD4 \u0D87\u0DAD.",
        "upgradeReminderCancel_action": "\u0DB4\u0DC3\u0DD4\u0DC0",
        "upgradeReminderTitle_msg": "\u0D86\u0DB0\u0DD2\u0D9A\u0DCA\u200D\u0DBA\u0DBA\u0DA7 \u0D8B\u0DAD\u0DCA\u0DC1\u0DCA\u200D\u0DBB\u0DDA\u0DAB\u0DD2\u0DBA!",
        "upgradeSystemWebView_msg": "\u0DC3\u0DDA\u0DC0\u0DCF\u0DAF\u0DCF\u0DBA\u0D9A\u0DBA \u0DC0\u0DD9\u0DAD \u0DC5\u0D9F\u0DCF \u0DC0\u0DD3\u0DB8\u0DA7 \u0DB1\u0DDC\u0DC4\u0DD0\u0D9A\u0DD2\u0DBA. \u0D94\u0DB6 \u0DB8\u0DCF\u0DBB\u0DCA\u0D9C\u0D85\u0DB4\u0D9C\u0DAD\u0DBA\u0DD2 \u0DC4\u0DDD \u0D87\u0DB1\u0DCA\u0DA9\u0DCA\u200D\u0DBB\u0DDC\u0DBA\u0DD2\u0DA9\u0DCA \u0DC0\u0DD2\u0DBA\u0DB8\u0DB1 \u0DAF\u0DD0\u0D9A\u0DCA\u0DB8 \u0DC4\u0DD2 \u0DB4\u0DBB\u0DAB \u0D85\u0DB1\u0DD4\u0DC0\u0DCF\u0DAF\u0DBA\u0D9A \u0DAF\u0DDD\u0DC2\u0DBA\u0D9A\u0DA7 \u0DB8\u0DD4\u0DC4\u0DD4\u0DAB \u0DAF\u0DD9\u0DBA\u0DD2. \u0D87\u0DB1\u0DCA\u0DA9\u0DCA\u200D\u0DBB\u0DDC\u0DBA\u0DD2\u0DA9\u0DCA \u0DC0\u0DD2\u0DBA\u0DB8\u0DB1 \u0DAF\u0DD0\u0D9A\u0DCA\u0DB8 \u0DB1\u0DC0\u0DAD\u0DB8 \u0D85\u0DB1\u0DD4\u0DC0\u0DCF\u0DAF\u0DBA\u0DA7 \u0D8B\u0DAD\u0DCA\u0DC1\u0DCA\u200D\u0DBB\u0DDA\u0DAB\u0DD2 \u0D9A\u0DBB\u0DB1\u0DCA\u0DB1:",
