        "businessOrPrivateUsage_label": "\u0412\u0438\u043A\u043E\u0440\u0438\u0441\u0442\u0430\u043D\u043D\u044F",
        "businessUseUpgradeNeeded_msg": "\u041D\u0430 \u0436\u0430\u043B\u044C, \u0432\u0430\u043C \u043D\u0430\u0440\u0430\u0437\u0456 \u0437\u0430\u0431\u043E\u0440\u043E\u043D\u0435\u043D\u043E \u043D\u0430\u0434\u0441\u0438\u043B\u0430\u0442\u0438 \u0442\u0430 \u043E\u0442\u0440\u0438\u043C\u0443\u0432\u0430\u0442\u0438 \u0435\u043B\u0435\u043A\u0442\u0440\u043E\u043D\u043D\u0456 \u043B\u0438\u0441\u0442\u0438 (\u0437\u0430 \u0432\u0438\u043D\u044F\u0442\u043A\u043E\u043C \u0441\u043B\u0443\u0436\u0431\u0438 \u043F\u0456\u0434\u0442\u0440\u0438\u043C\u043A\u0438 Tutanota \u0437\u0430 \u0430\u0434\u0440\u0435\u0441\u043E\u044E sales@tutao.de), \u043E\u0441\u043A\u0456\u043B\u044C\u043A\u0438 \u0443 \u0432\u0430\u0441 \u0454 \u0440\u043E\u0437\u0440\u0430\u0445\u0443\u043D\u043A\u043E\u0432\u0438\u0439 \u0440\u0430\u0445\u0443\u043D\u043E\u043A, \u0434\u043E\u0437\u0432\u043E\u043B\u0435\u043D\u0438\u0439 \u043B\u0438\u0448\u0435 \u0437 \u043E\u043F\u043B\u0430\u0447\u0435\u043D\u043E\u044E \u043F\u0456\u0434\u043F\u0438\u0441\u043A\u043E\u044E. \u041F\u0435\u0440\u0435\u0439\u0434\u0456\u0442\u044C \u0437\u0430\u0440\u0430\u0437 \u0434\u043E \u043F\u043B\u0430\u0442\u043D\u043E\u0457 \u043F\u0456\u0434\u043F\u0438\u0441\u043A\u0438.",
        "buyEmailAliasInfo_msg": "\u0414\u043B\u044F \u0437\u043C\u0456\u043D\u0438 \u043A\u0456\u043B\u044C\u043A\u043E\u0441\u0442\u0456 \u043D\u0430\u044F\u0432\u043D\u0438\u0445 \u043F\u0441\u0435\u0432\u0434\u043E\u043D\u0456\u043C\u0456\u0432 \u0435\u043B. \u043F\u043E\u0448\u0442\u0438 \u043E\u0431\u0435\u0440\u0456\u0442\u044C, \u0431\u0443\u0434\u044C \u043B\u0430\u0441\u043A\u0430, \u043E\u0434\u0438\u043D \u0437 \u043F\u0430\u043A\u0435\u0442\u0456\u0432 \u043F\u0441\u0435\u0432\u0434\u043E\u043D\u0456\u043C\u0456\u0432 \u0435\u043B. \u043F\u043E\u0448\u0442\u0438. \u0417\u0430\u0431\u0440\u043E\u043D\u044C\u043E\u0432\u0430\u043D\u0456 \u043F\u0441\u0435\u0432\u0434\u043E\u043D\u0456\u043C\u0438 \u0435\u043B. \u043F\u043E\u0448\u0442\u0438 \u043C\u043E\u0436\u0443\u0442\u044C \u0431\u0443\u0442\u0438 \u0432\u0438\u043A\u043E\u0440\u0438\u0441\u0442\u0430\u043D\u0456 \u0431\u0443\u0434\u044C-\u044F\u043A\u0438\u043C \u043A\u043E\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0435\u043C.",
        "buyGiftCard_label": "\u041F\u0440\u0438\u0434\u0431\u0430\u0439\u0442\u0435 \u043F\u043E\u0434\u0430\u0440\u0443\u043D\u043A\u043E\u0432\u0443 \u043A\u0430\u0440\u0442\u0443",
        "buyStorageCapacityInfo_msg": "\u0411\u0443\u0434\u044C \u043B\u0430\u0441\u043A\u0430, \u0432\u0438\u0431\u0435\u0440\u0456\u0442\u044C \u043E\u0434\u0438\u043D \u0437 \u043F\u0430\u043A\u0435\u0442\u0456\u0432 \u0437\u0431\u0435\u0440\u0456\u0433\u0430\u043D\u043D\u044F, \u0449\u043E\u0431 \u0437\u043C\u0456\u043D\u0438\u0442\u0438 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u0443 \u0454\u043C\u043D\u0456\u0441\u0442\u044C \u0441\u0445\u043E\u0432\u0438\u0449\u0430. \u0417\u0430\u043C\u043E\u0432\u043B\u0435\u043D\u0435 \u0441\u0445\u043E\u0432\u0438\u0449\u0435 \u043D\u0430\u0434\u0430\u0454\u0442\u044C\u0441\u044F \u0432\u0441\u0456\u043C \u043A\u043E\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430\u043C.",
