        "creditCardNumberFormat_msg": "\u0412\u0432\u0435\u0434\u0456\u0442\u044C, \u0431\u0443\u0434\u044C \u043B\u0430\u0441\u043A\u0430, \u043D\u043E\u043C\u0435\u0440 \u0432\u0430\u0448\u043E\u0457 \u043A\u0440\u0435\u0434\u0438\u0442\u043D\u043E\u0457 \u043A\u0430\u0440\u0442\u043A\u0438.",
        "creditCardNumberInvalid_msg": "\u041D\u043E\u043C\u0435\u0440 \u043A\u0440\u0435\u0434\u0438\u0442\u043D\u043E\u0457 \u043A\u0430\u0440\u0442\u043A\u0438 \u043D\u0435\u0434\u0456\u0439\u0441\u043D\u0438\u0439.",
        "creditCardNumber_label": "\u041D\u043E\u043C\u0435\u0440 \u043A\u0440\u0435\u0434\u0438\u0442\u043D\u043E\u0457 \u043A\u0430\u0440\u0442\u043A\u0438",
        "creditCardPaymentErrorVerificationNeeded_msg": "\u0411\u0443\u0434\u044C \u043B\u0430\u0441\u043A\u0430, \u043E\u043D\u043E\u0432\u0456\u0442\u044C \u0441\u0432\u043E\u0457 \u043F\u043B\u0430\u0442\u0456\u0436\u043D\u0456 \u0434\u0430\u043D\u0456. \u0426\u0435 \u0441\u043F\u0440\u0438\u0447\u0438\u043D\u0438\u0442\u044C \u043F\u0435\u0440\u0435\u0432\u0456\u0440\u043A\u0443 \u043A\u0440\u0435\u0434\u0438\u0442\u043D\u043E\u0457 \u043A\u0430\u0440\u0442\u043A\u0438 \u0437\u0433\u0456\u0434\u043D\u043E \u0437 \u0432\u0438\u043C\u043E\u0433\u0430\u043C\u0438 \u0432\u0430\u0448\u043E\u0433\u043E \u0431\u0430\u043D\u043A\u0443.",
        "creditCardPendingVerification_msg": "\u041F\u0435\u0440\u0435\u0432\u0456\u0440\u043A\u0430 \u0432\u0430\u0448\u043E\u0457 \u043A\u0440\u0435\u0434\u0438\u0442\u043D\u043E\u0457 \u043A\u0430\u0440\u0442\u043A\u0438 \u0449\u0435 \u043D\u0435 \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0430. \u042F\u043A\u0449\u043E \u043F\u0440\u043E\u0431\u043B\u0435\u043C\u0430 \u043D\u0435 \u0437\u043D\u0438\u043A\u043D\u0435, \u0441\u043F\u0440\u043E\u0431\u0443\u0439\u0442\u0435 \u043F\u0435\u0440\u0435\u0432\u0456\u0440\u0438\u0442\u0438 \u043A\u0430\u0440\u0442\u043A\u0443 \u043F\u0456\u0437\u043D\u0456\u0448\u0435.",
        "creditCardVerificationFailed_msg": "\u041D\u0430 \u0436\u0430\u043B\u044C, \u043D\u0435 \u0432\u0434\u0430\u043B\u043E\u0441\u044F \u043F\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0438 \u0432\u0430\u0448\u0443 \u043A\u0440\u0435\u0434\u0438\u0442\u043D\u0443 \u043A\u0430\u0440\u0442\u043A\u0443. \u0421\u043F\u0440\u043E\u0431\u0443\u0439\u0442\u0435 \u0449\u0435 \u0440\u0430\u0437 \u0430\u0431\u043E \u0432\u0438\u0431\u0435\u0440\u0456\u0442\u044C \u0456\u043D\u0448\u0438\u0439 \u0441\u043F\u043E\u0441\u0456\u0431 \u043E\u043F\u043B\u0430\u0442\u0438.",
        "creditCardVerificationLimitReached_msg": "\u0414\u043E\u0441\u044F\u0433\u043D\u0443\u0442\u043E \u0433\u0440\u0430\u043D\u0438\u0447\u043D\u043E\u0457 \u043A\u0456\u043B\u044C\u043A\u043E\u0441\u0442\u0456 \u043F\u0435\u0440\u0435\u0432\u0456\u0440\u043E\u043A \u043A\u0440\u0435\u0434\u0438\u0442\u043D\u043E\u0457 \u043A\u0430\u0440\u0442\u043A\u0438. \u041F\u043E\u0432\u0442\u043E\u0440\u0456\u0442\u044C \u0441\u043F\u0440\u043E\u0431\u0443 \u0447\u0435\u0440\u0435\u0437 \u043A\u0456\u043B\u044C\u043A\u0430 \u0433\u043E\u0434\u0438\u043D \u0456 \u043F\u0435\u0440\u0435\u043A\u043E\u043D\u0430\u0439\u0442\u0435\u0441\u044F, \u0449\u043E \u0432\u0432\u0435\u0434\u0435\u043D\u0456 \u0434\u0430\u043D\u0456 \u0454 \u0434\u0456\u0439\u0441\u043D\u0438\u043C\u0438.  \u042F\u043A\u0449\u043E \u043F\u043E\u0434\u0430\u043B\u044C\u0448\u0456 \u043F\u0435\u0440\u0435\u0432\u0456\u0440\u043A\u0438 \u043D\u0435 \u0434\u0430\u0434\u0443\u0442\u044C \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0456\u0432, \u0437\u0432'\u044F\u0436\u0456\u0442\u044C\u0441\u044F \u0437\u0456 \u0441\u0432\u043E\u0457\u043C \u0431\u0430\u043D\u043A\u043E\u043C. ",
        "creditCardVerificationNeededPopup_msg": "\u0412\u0430\u0448\u0443 \u043A\u0440\u0435\u0434\u0438\u0442\u043D\u0443 \u043A\u0430\u0440\u0442\u043A\u0443 \u043F\u043E\u0442\u0440\u0456\u0431\u043D\u043E \u043F\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0438 \u0443 \u0441\u0432\u043E\u0454\u043C\u0443 \u0431\u0430\u043D\u043A\u0443. \u0414\u043B\u044F \u0446\u044C\u043E\u0433\u043E \u0431\u0443\u0434\u0435 \u0432\u0456\u0434\u043A\u0440\u0438\u0442\u043E \u043D\u043E\u0432\u0435 \u0432\u0456\u043A\u043D\u043E.",
        "creditCardVerification_msg": "\u0412\u0430\u0448\u0443 \u043A\u0440\u0435\u0434\u0438\u0442\u043D\u0443 \u043A\u0430\u0440\u0442\u043A\u0443 \u0431\u0443\u0434\u0435 \u0437\u0430\u0440\u0430\u0437 \u043F\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0435\u043D\u043E...",
        "creditUsageOptions_msg": '\u041A\u0440\u0435\u0434\u0438\u0442 \u043C\u043E\u0436\u0435 \u0431\u0443\u0442\u0438 \u0432\u0438\u043A\u043E\u0440\u0438\u0441\u0442\u0430\u043D\u0438\u0439 \u0434\u043B\u044F \u043F\u0440\u0438\u0434\u0431\u0430\u043D\u043D\u044F \u0440\u0456\u0437\u043D\u0438\u0445 \u043F\u0430\u043A\u0435\u0442\u0456\u0432 (\u043F\u0435\u0440\u0435\u0439\u0434\u0456\u0442\u044C \u0434\u043E "\u041D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u043D\u044F \u21E8 \u041F\u0456\u0434\u043F\u0438\u0441\u043A\u0430" \u043F\u0456\u0441\u043B\u044F \u0432\u0445\u043E\u0434\u0443 \u0432 \u0441\u0438\u0441\u0442\u0435\u043C\u0443) \u0430\u0431\u043E \u043C\u043E\u0436\u0435 \u0431\u0443\u0442\u0438 \u0443\u0442\u0440\u0438\u043C\u0430\u043D\u0438\u0439 \u0434\u043E \u043D\u0430\u0441\u0442\u0443\u043F\u043D\u043E\u0433\u043E \u043F\u0435\u0440\u0456\u043E\u0434\u0443 \u043F\u0456\u0434\u043F\u0438\u0441\u043A\u0438 \u0434\u043B\u044F \u043E\u043F\u043B\u0430\u0442\u0438 \u043F\u043E\u043D\u043E\u0432\u043B\u0435\u043D\u043D\u044F. \u041A\u0440\u0435\u0434\u0438\u0442, \u0441\u0442\u0432\u043E\u0440\u0435\u043D\u0438\u0439 \u0437 \u043F\u043E\u0434\u0430\u0440\u0443\u043D\u043A\u043E\u0432\u0438\u0445 \u043A\u0430\u0440\u0442\u043E\u043A, \u043D\u0435 \u043C\u0430\u0454 \u0442\u0435\u0440\u043C\u0456\u043D\u0443 \u0434\u0456\u0457!',
        "credit_label": "\u041A\u043E\u0448\u0442\u0438 \u043D\u0430 \u0440\u0430\u0445\u0443\u043D\u043A\u0443",
